L3_1 = {}
L3_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 422
L3_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "KNIGHT_NPC_NULL_NULL"
L3_1.m_Pos = "L"
L3_1.m_Talk_KOREA = "대장님, 저기 보십시오! 구원자님이십니다!"
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "隊長、あちらを見てください！　救世主様です！"
L3_1.m_Talk_ENG = "Look, Captain! The Savior is coming!"
L3_1.m_Talk_TWN = "隊長，快看那邊！是救贖者大人！"
L3_1.m_Talk_THA = "ดูสิครับ นายกอง! พระผู้ไถ่กำลังมาแล้ว!"
L3_1.m_Talk_VTN = "Xem kìa, Đội Trưởng! Đấng Cứu Thế đang tới!"
L3_1.m_Talk_SCN = "队长，快看那边！是救赎者大人！"
L3_1.m_Talk_DEU = "Hauptmann, schauen Sie mal dort! Der Erlöser ist gekommen!"
L3_1.m_Talk_FRA = "Capitaine, regardez ! Le Sauveur est de retour !"
L4_1 = {}
L4_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 422
L4_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "KNIGHT_NPC_CHIEF_NULL"
L4_1.m_Pos = "R"
L4_1.m_Talk_KOREA = "오셨군요. 방금 막 보초들에게 혼자 가셨다는 말을 전해 들은 참이었습니다."
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "戻られたんですね。先ほど見張りから一人でどこかへ向かわれたという話を聞いたところでした。"
L4_1.m_Talk_ENG = "You have arrived. I have just heard from the guards that you went alone."
L4_1.m_Talk_TWN = "您來了。我剛聽站崗的人說您一個人走了。"
L4_1.m_Talk_THA = "มาแล้วหรือครับ กระผมเพิ่งทราบจากองครักษ์ว่าท่านออกไปคนเดียว"
L4_1.m_Talk_VTN = "Ngài tới rồi. Tôi vừa nghe hộ vệ nói ngài đi một mình."
L4_1.m_Talk_SCN = "您来了。我刚听站岗的人说您一个人走了。"
L4_1.m_Talk_DEU = "Da sind Sie ja. Ich habe gerade von den Wachen gehört, dass Sie einfach alleine losgezogen sind."
L4_1.m_Talk_FRA = "Vous voilà. Les gardes venaient juste de m'informer que vous étiez parti tout seul."
L5_1 = {}
