L6_1 = {}
L6_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 422
L6_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_LAUGH"
L6_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L6_1.m_Pos = "C"
L6_1.m_Talk_KOREA = "네. 정식으로 보고했다간 다른 분들도 따라오셔야 할 테니까요."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "はい、正式に報告したら、他の皆さんもついてこないといけなくなりますから。"
L6_1.m_Talk_ENG = "Yes. If I were to make an official report, the others would have to follow."
L6_1.m_Talk_TWN = "沒錯，因為正式報告的話，各位也都會跟過來吧。"
L6_1.m_Talk_THA = "ครับ เพราะถ้าผมรายงานเป็นทางการไป คนอื่นๆ คงตามไปด้วย"
L6_1.m_Talk_VTN = "Đúng vậy. Nếu tôi làm báo cáo chính thức, những người khác cũng sẽ phải đi theo."
L6_1.m_Talk_SCN = "没错，要是我正式汇报的话，各位也都会跟过来吧。"
L6_1.m_Talk_DEU = "Ja. Wenn ich es offiziell gemeldet hätte, dann hätten die anderen mir folgen müssen."
L6_1.m_Talk_FRA = "En effet. Car si j'avais fait un rapport officiel, les autres seraient venus avec moi."
L7_1 = {}
L7_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 422
L7_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L7_1.m_Pos = "C"
L7_1.m_Talk_KOREA = "걱정하게 만들었다면 죄송합니다."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "心配かけて申し訳ありません。"
L7_1.m_Talk_ENG = "I apologize if I made you worry."
L7_1.m_Talk_TWN = "抱歉，讓大家擔心了。"
L7_1.m_Talk_THA = "ขอโทษด้วยนะครับที่ทำให้เป็นกังวล"
L7_1.m_Talk_VTN = "Tôi xin lỗi nếu tôi làm các anh lo lắng."
L7_1.m_Talk_SCN = "抱歉，让大家担心了。"
L7_1.m_Talk_DEU = "Es tut mir leid, wenn ich Ihnen Sorgen bereitet habe."
L7_1.m_Talk_FRA = "Désolé si je vous ai inquiété."
