L10_1 = {}
L10_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 422
L10_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "KNIGHT_NPC_CHIEF_NULL"
L10_1.m_Pos = "R"
L10_1.m_Talk_KOREA = "천만에요. 아무 일 없으셔서 다행입니다."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "いいえ。ご無事で何よりです。"
L10_1.m_Talk_ENG = "No need. I am only glad that you are back, safe and sound."
L10_1.m_Talk_TWN = "哪裡的話，您沒事就好。"
L10_1.m_Talk_THA = "ไม่ต้องหรอกครับ กระผมเพียงดีใจที่ท่านกลับมาอย่างปลอดภัย ไม่มีอะไรบอบช้ำ"
L10_1.m_Talk_VTN = "Không sao. Tôi chỉ vui vì ngài đã trở lại an toàn."
L10_1.m_Talk_SCN = "哪里的话，您没事就好。"
L10_1.m_Talk_DEU = "Schon gut. Ich bin einfach erleichtert, dass Sie unversehrt zurückgekehrt sind."
L10_1.m_Talk_FRA = "N'en parlons plus. Vous êtes sain et sauf, c'est l'essentiel."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 422
L11_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "KNIGHT_NPC_CHIEF_NULL"
L11_1.m_Pos = "R"
L11_1.m_Talk_KOREA = "하지만 위험을 무릅쓰진 말아 주십시오. 구원자님께서는 저희의 희망이시니까요."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "しかしあまり危険を顧みないことはおやめください。救世主様は我々の希望ですから。"
L11_1.m_Talk_ENG = "Alas, I will have to ask you to be careful next time. You are our only hope."
L11_1.m_Talk_TWN = "不過請您不要冒險，因為救贖者大人您是我們的希望。"
L11_1.m_Talk_THA = "แต่ยังไง กระผมคงต้องขอให้คราวหน้าท่านระวังตัวหน่อยนะครับ ท่านเป็นความหวังเดียวของพวกเราแล้ว"
L11_1.m_Talk_VTN = "Trời ạ, nhưng lần sau tôi mong ngài hãy cẩn thận. Ngài là hy vọng duy nhất của chúng tôi."
L11_1.m_Talk_SCN = "不过请不要冒险，救赎者大人，您一直是我们的希望啊。"
L11_1.m_Talk_DEU = "Aber ich muss Sie bitten, keine Risiken mehr einzugehen. Sie sind nämlich unsere einzige Hoffnung."
L11_1.m_Talk_FRA = "Hélas, je dois vous demander de faire plus attention. Vous êtes notre seul espoir, ne l'oubliez pas."
