L14_1 = {}
L14_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 422
L14_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_StartFXSoundName = "FX_COMBAT_ALL_FOOT_STEP_LANDING_SMALL_02"
L14_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L14_1.m_Pos = "C"
L14_1.m_Talk_KOREA = "아니. 군법에 어긋나는 행동을 저질렀다는 사실 자체가 중요해."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "いや、今回は軍法に背いたということ自体が問題だ。"
L14_1.m_Talk_ENG = "No, the fact that he disobeyed the rules needs to be discussed."
L14_1.m_Talk_TWN = "不，做出違反軍法的行為這件事本身也很重要。"
L14_1.m_Talk_THA = "ไม่ได้ ยังไงเรื่องไม่ทำตามกฎก็ต้องคุยกัน"
L14_1.m_Talk_VTN = "Không được, việc ngài ấy vi phạm quy định cần phải được thảo luận."
L14_1.m_Talk_SCN = "不，做出违反军法的行为这件事本身也很重要。"
L14_1.m_Talk_DEU = "Nein, die Tatsache, dass er gegen die Regeln verstoßen hat, darf nicht so einfach ignoriert werden."
L14_1.m_Talk_FRA = "Non. Il a désobéi à nos règles, c'est un problème qui doit être discuté."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 422
L15_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L15_1.m_Pos = "C"
L15_1.m_Talk_KOREA = "알렌. 기다리고 있었어?"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "アレン、待っていたの？"
L15_1.m_Talk_ENG = "Allen. Were you waiting?"
L15_1.m_Talk_TWN = "艾倫，你是在等我嗎？"
L15_1.m_Talk_THA = "อัลเลน รอผมอยู่เหรอครับ?"
L15_1.m_Talk_VTN = "Allen. Anh đang chờ tôi sao?"
L15_1.m_Talk_SCN = "艾伦，你是在等我吗？"
L15_1.m_Talk_DEU = "Allen. Hast du auf mich gewartet?"
L15_1.m_Talk_FRA = "Allen. Tu m'attendais, toi aussi ?"
L16_1 = {}
