L17_1 = {}
L17_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 422
L17_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_DESPAIR"
L17_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L17_1.m_Pos = "L"
L17_1.m_Talk_KOREA = "당연하지. 전력의 핵심이 사라졌는데."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "当たり前だ。最も重要な戦力がどこかにいなくなったんだ。"
L17_1.m_Talk_ENG = "Of course I was. You’re the pillar of our forces."
L17_1.m_Talk_TWN = "作為戰鬥力核心的人員失蹤了，我當然會如此。"
L17_1.m_Talk_THA = "แน่นอนว่าต้องรอ นายคือเสาหลักของกองกำลังเรานะ"
L17_1.m_Talk_VTN = "Dĩ nhiên. Cậu là trụ cột trong lực lượng của chúng ta."
L17_1.m_Talk_SCN = "作为战斗力核心的人员失踪了，我当然会如此。"
L17_1.m_Talk_DEU = "Natürlich. Du bist der Kern unserer Streitkräfte."
L17_1.m_Talk_FRA = "Bien évidemment. Où serais-je allé sans notre arme principale ?"
L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 422
L18_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_StartFXSoundName = "FX_COMBAT_ALL_FOOT_STEP_LANDING_SMALL_02"
L18_1.m_CharStrID = "KNIGHT_NPC_CHIEF_NULL"
L18_1.m_Pos = "R_M_I"
L18_1.m_Talk_KOREA = "죄송합니다, 단장님! 저희 대응이 늦어져서 그만……!"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "申し訳ありません団長！　対応が遅くなってしまったせいで……！"
L18_1.m_Talk_ENG = "I'm sorry, Commander! Our response was too late...!"
L18_1.m_Talk_TWN = "對不起，團長！因為我們反應慢了……！"
L18_1.m_Talk_THA = "ขอโทษครับ ผู้บัญชาการ! พวกเราจัดการเรื่องนี้ช้าไป...!"
L18_1.m_Talk_VTN = "Tôi xin lỗi, Chỉ Huy! Chúng tôi đã phản ứng quá chậm...!"
L18_1.m_Talk_SCN = "对不起，团长！因为我们反应慢了……！"
L18_1.m_Talk_DEU = "Entschuldigung, Captain! Wir haben zu spät reagiert ...!"
L18_1.m_Talk_FRA = "Veuillez m'excuser, commandant ! Nous n'avons pas réagi assez vite !"
L19_1 = {}
L19_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 422
L19_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L19_1.m_Pos = "L"
L19_1.m_Talk_KOREA = "책임을 물을 생각은 없다. 원인은 일탈을 벌인 구원자가 제공했으니까."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "責任を問うつもりはない。原因は逸脱を犯した救世主本人だからな。"
L19_1.m_Talk_ENG = "I'm not here to make anyone else responsible, since it was the Savior who left his post without notice."
L19_1.m_Talk_TWN = "我不想追究你的責任。相反，這是擅自離隊的救贖者所造成的結果。"
L19_1.m_Talk_THA = "ผมไม่ได้มาหาความรับผิดชอบจากใครที่ไหนนะ เพราะคนที่ออกไปไม่บอกกล่าวก็คือตัวพระผู้ไถ่"
L19_1.m_Talk_VTN = "Tôi không ở đây để quy kết trách nhiệm cho bất kỳ ai khác, vì chính Đấng Cứu Thế đã lén lút rời khỏi vị trí của mình."
L19_1.m_Talk_SCN = "我不想追究你的责任。相反，这是擅自离队的救赎者所造成的结果。"
L19_1.m_Talk_DEU = "Ich bin nicht hier, um jemand anderen zur Verantwortung zu ziehen, da es der Erlöser selbst war, der seinen Posten ohne Vorankündigung verlassen hat."
L19_1.m_Talk_FRA = "Je ne suis pas ici pour te blâmer. C'est le Sauveur, et lui seul, qui a quitté son poste sans en informer personne."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 422
L20_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_IDLE"
L20_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L20_1.m_Pos = "L"
L20_1.m_Talk_KOREA = "얘기를 나눠야 하는데, 잠시 병사들을 데리고 자리를 비켜 주겠나?"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "少し話し合いがしたいのだが、しばらく兵士たちを連れて、席を外してくれないか？"
L20_1.m_Talk_ENG = "I need a word with him in private. Will all of you excuse us for a moment?"
L20_1.m_Talk_TWN = "我要和他談談，你能帶著士兵先離開嗎？"
L20_1.m_Talk_THA = "ผมอยากคุยกับเขาสองคน ขอเราอยู่กันตามลำพังสักครู่ได้มั้ย?"
L20_1.m_Talk_VTN = "Tôi cần nói chuyện riêng với ngài ấy. Các anh cho chúng tôi chút thời gian được chứ?"
L20_1.m_Talk_SCN = "我要和他谈谈，你能带着士兵先离开吗？"
L20_1.m_Talk_DEU = "Wir müssen etwas unter vier Augen besprechen. Könnten Sie uns alle kurz entschuldigen?"
L20_1.m_Talk_FRA = "J'ai besoin de discuter avec lui en privé. Vous pouvez nous excuser un moment ?"
L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 422
L21_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "KNIGHT_NPC_CHIEF_NULL"
L21_1.m_Pos = "R"
L21_1.m_Talk_KOREA = "예, 알겠습니다!"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "はい、かしこまりました！"
L21_1.m_Talk_ENG = "Yes, sir!"
L21_1.m_Talk_TWN = "是，明白！"
L21_1.m_Talk_THA = "ครับผม!"
L21_1.m_Talk_VTN = "Vâng, thưa ngài!"
L21_1.m_Talk_SCN = "是，明白！"
L21_1.m_Talk_DEU = "Jawohl!"
L21_1.m_Talk_FRA = "Bien, monsieur !"
L22_1 = {}
