L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 422
L23_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L23_1.m_Pos = "C"
L23_1.m_Talk_KOREA = "내일이 출정식이다. 설마 잊은 건 아니겠지?"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "明日は出征式だ。まさか忘れたわけではないだろうな？"
L23_1.m_Talk_ENG = "The ceremony of war is going to be held tomorrow. Or did you already forget that?"
L23_1.m_Talk_TWN = "明天是出征儀式。你不會忘了吧？"
L23_1.m_Talk_THA = "เราจะทำพิธีในการสงครามกันพรุ่งนี้แล้วนะ หรือว่านายลืมไปแล้ว?"
L23_1.m_Talk_VTN = "Lễ ra quân sẽ được tổ chức vào ngày mai. Hay cậu đã quên rồi?"
L23_1.m_Talk_SCN = "明天是远征仪式。你不会忘了吧？"
L23_1.m_Talk_DEU = "Die Kriegszeremonie findet morgen statt. Oder hast du das etwa schon vergessen?"
L23_1.m_Talk_FRA = "La cérémonie a lieu demain. Tu n'as pas oublié, j'espère ?"
L24_1 = {}
L24_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 422
L24_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_IDLE"
L24_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "물론이지. 기억하고 있어."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "もちろん。覚えているよ。"
L24_1.m_Talk_ENG = "Of course not. I remember."
L24_1.m_Talk_TWN = "我當然記得。"
L24_1.m_Talk_THA = "ผมต้องจำได้อยู่แล้วครับ"
L24_1.m_Talk_VTN = "Dĩ nhiên là không. Tôi nhớ mà."
L24_1.m_Talk_SCN = "我当然记得。"
L24_1.m_Talk_DEU = "Natürlich nicht. Ich erinnere mich."
L24_1.m_Talk_FRA = "Bien sûr que non. Je m'en souviens."
