L27_1 = {}
L27_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 422
L27_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_LAUGH"
L27_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L27_1.m_Pos = "L"
L27_1.m_Talk_KOREA = "어젯밤엔 루크레시아가 말해 줘서 전하께서 서실 연단도 보러 갔거든. 정말 멋지더라."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "昨夜はルクレシアが言ってくれて、殿下がお立ちになる演壇も見てきたんだ。すごかったよ。"
L27_1.m_Talk_ENG = "I even went to see the podium that His Highness is going to stand on yesterday. Lucrecia told me about it. It looked great."
L27_1.m_Talk_TWN = "昨晚露可蕾西亞告訴我了，我還特意去看了殿下要站的講台。很是雄偉。"
L27_1.m_Talk_THA = "เมื่อวานผมไปดูแท่นพิธีที่ฝ่าบาทต้องขึ้นไปยืนมาแล้วด้วย ลูเครเซียเป็นคนบอก มันสวยมากเลยครับ"
L27_1.m_Talk_VTN = "Tôi thậm chí đã đi xem bục phát biểu mà Điện Hạ sẽ đứng vào ngày mai. Lucrecia đã kể cho tôi. Nó trông rất tuyệt."
L27_1.m_Talk_SCN = "昨晚卢克雷西亚告诉我了，我还特意去看了殿下要站的讲台。很是雄伟。"
L27_1.m_Talk_DEU = "Ich habe mir gestern Nacht sogar das Podium angesehen, auf dem Seine Hoheit stehen wird. Lucrecia hat mir davon erzählt. Es sah großartig aus."
L27_1.m_Talk_FRA = "Je suis même allé voir l'estrade où Son Altesse se tiendra demain, elle est impressionnante. C'est Lucrecia qui m'en a parlé."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 422
L28_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L28_1.m_Pos = "R"
L28_1.m_Talk_KOREA = "그리고 가서 전하 얘기만 실컷 했고?"
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "それで、そこでルクレシアに殿下の話ばかりして終わったのか？"
L28_1.m_Talk_ENG = "I'm guessing you just talked about His Highness to Lucrecia the whole time."
L28_1.m_Talk_TWN = "你一直在和露可蕾西亞聊殿下的事？"
L28_1.m_Talk_THA = "ผมเดาว่านายคงพูดถึงฝ่าบาทอยู่ตลอดเลยสินะ"
L28_1.m_Talk_VTN = "Tôi đoán hai người đã nói về Điện Hạ suốt thời gian qua."
L28_1.m_Talk_SCN = "所以我猜，你一直在和卢克雷西亚聊殿下的事？"
L28_1.m_Talk_DEU = "Ich vermute, du hast die ganze Zeit lang nur über Seine Hoheit mit Lucrecia gesprochen."
L28_1.m_Talk_FRA = "Et je suppose que tu as parlé de Son Altesse à Lucrecia, après ?"
L29_1 = {}
L29_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE2@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 422
L29_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_IDLE"
L29_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L29_1.m_Pos = "L"
L29_1.m_Talk_KOREA = "응. 무슨 문제라도 있어?"
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "うん、何か問題でも？"
L29_1.m_Talk_ENG = "Yes. Is there a problem with that?"
L30_1 = "嗯，有什麼問題嗎？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ครับ มันจะเป็นปัญหาอะไรรึเปล่าครับ?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Đúng vậy. Có vấn đề gì sao?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "嗯，有什么问题吗？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ja. Gibt es ein Problem?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Oui. Pourquoi, il ne fallait pas ?"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP10_ACT1_INTERLUDE2@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 30
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 422
L30_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L30_1.m_Pos = "R"
L31_1 = "아주 많은 문제가 있지. 루크레시아도 고민이 많겠군."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ああ問題大ありだ。ルクレシアの心労がうかがえるな。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "There are a lot of problems with that. Lucrecia must be in distress."
L30_1.m_Talk_ENG = L31_1
L31_1 = "當然……露可蕾西亞大概會很不開心吧。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เยอะเลยล่ะ ลูเครเซียต้องเจ็บปวดแน่"
L30_1.m_Talk_THA = L31_1
L31_1 = "Có rất nhiều \"sao\" đấy. Lucrecia hẳn đang rất đau khổ."
L30_1.m_Talk_VTN = L31_1
L31_1 = "当然……卢克雷西亚大概会很不开心吧。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Es gibt recht viele Probleme. Lucrecia macht sich bestimmt große Sorgen um dich."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Non, il ne fallait pas. Lucrecia doit être dans la tourmente à l'heure qu'il est."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 422
L31_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L31_1.m_bWaitClick = false
L31_1.m_fWaitTime = 0
