L32_1 = {}
L33_1 = "EP10_ACT1_INTERLUDE2@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 422
L32_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "아무튼, 마왕은 이제까지 상대했던 적들과 격이 달라."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "とにかく、魔王はこれまでの相手とは格が違う。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Anyway, the Demon Lord is nothing like the ones we've come across so far."
L32_1.m_Talk_ENG = L33_1
L33_1 = "總之，魔王與以往的對手不同。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แต่เอาเถอะ เจ้าแห่งดีม่อนไม่เหมือนใครทั้งนั้น เรามากันไกลมากแล้ว"
L32_1.m_Talk_THA = L33_1
L33_1 = "Dù sao, Chúa Quỷ không giống như bất kỳ sinh vật nào chúng ta đã gặp cho đến giờ."
L32_1.m_Talk_VTN = L33_1
L33_1 = "总之，魔王与以往的对手不同。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wie auch immer, der Dämonenfürst ist viel stärker als all die anderen Gegner, die uns bisher begegnet sind."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Quoi qu'il en soit, tu dois comprendre que la puissance du Seigneur démon n'a rien à voir celle de nos adversaires précédents."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP10_ACT1_INTERLUDE2@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 422
L33_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "단독 행동은 절대 안 돼. 이번만큼은 철저하게 내 지휘에 따라 줘야 한다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "単独行動は許されない。今回ばかりは徹底的に私の指揮に従ってもらう。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "No more going off on your own. This time, you follow my orders only."
L33_1.m_Talk_ENG = L34_1
L34_1 = "你絕對不能單獨行動。這次必須嚴格聽從我的指揮。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "อย่าเที่ยวออกไปเองอีกล่ะ คราวนี้ต้องทำตามคำสั่งผมนะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Không được tự ý ra ngoài nữa. Lần này, cậu chỉ được nghe lệnh tôi."
L33_1.m_Talk_VTN = L34_1
L34_1 = "你绝对不能单独行动。这次必须严格听从我的指挥。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ab jetzt darfst du nicht mehr auf eigene Faust einfach losziehen. Dieses Mal musst du meine Anweisungen strikt befolgen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Tu dois arrêter de filer en douce comme ça. Cette fois-ci, tu dois faire ce que je te dirai."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP10_ACT1_INTERLUDE2@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 422
L34_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L34_1.m_Pos = "C"
L35_1 = "알겠어. 알렌의 지휘는 믿을 수 있으니까."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "わかったよ。アレンの指揮は信用できるから。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Okay. You know I trust you, Allen."
L34_1.m_Talk_ENG = L35_1
L35_1 = "好，因為艾倫的指揮一直都很可靠的嘛。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ครับ ผมรู้ว่าไว้ใจคุณได้ อัลเลน"
L34_1.m_Talk_THA = L35_1
L35_1 = "Được. Anh biết tôi tin anh mà, Allen."
L34_1.m_Talk_VTN = L35_1
L35_1 = "好，因为艾伦的指挥一直都很可靠的嘛。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Okay. Du weißt, dass ich dir vertraue, Allen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "D'accord. Je te fais confiance, Allen."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP10_ACT1_INTERLUDE2@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 422
L35_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "전하나 너나, 그렇게 말해 놓고 마음대로 행동한 적이 한두 번이었어야지."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "殿下も君も、そう言うだけ言って、勝手に行動した例が多すぎる。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I also know you and His Highness always somehow fail to do so."
L35_1.m_Talk_ENG = L36_1
L36_1 = "不管是殿下還是你，都經常這樣口頭上答應，之後卻還是隨意行動。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "และผมก็รู้ด้วยว่าทั้งนายทั้งฝ่าบาททำไม่ได้อยู่เรื่อย ไม่รู้ทำไม"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi cũng biết cậu và Điện Hạ luôn luôn chẳng làm được như vậy."
L35_1.m_Talk_VTN = L36_1
L36_1 = "不管是殿下还是你，都经常这样口头上答应，之后却还是随意行动。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Sowohl du als auch Seine Hoheit habt mir bereits ein paar Mal zugesichert auf mich zu hören und habt dann trotzdem auf eigene Faust gehandelt."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Et pourtant, tu continues de faire les quatre cent coups. Incorrigible, comme Son Altesse."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
