L38_1.m_Face = "UNIT_LAUGH"
L39_1 = "PRINCE_KNIGHT_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "R"
L39_1 = "호오, 알렌 경. 상당히 대범해지지 않았나. 주둔지에서 황족의 험담을 늘어 놓다니."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ほう、アレン。いつからそんなに大胆になったんだ？　駐屯地で皇族の悪口を言うとは。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "You've become bold, Sir Allen. Talking about royalty like that."
L38_1.m_Talk_ENG = L39_1
L39_1 = "呵呵，很大膽嘛，艾倫卿。竟然在背地裡說皇室的壞話。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "กล้ามากนะเซอร์อัลเลน ที่พูดถึงเชื้อพระวงศ์เยี่ยงนั้นน่ะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ngài đã trở nên liều hơn rồi, Ngài Allen à, khi dám nói về hoàng gia bằng giọng điệu đó."
L38_1.m_Talk_VTN = L39_1
L39_1 = "呵呵，很大胆嘛，艾伦爵士。竟然在背地里说皇族的坏话。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Oho, Sir Allen. Wie mutig von dir, so abwertend über die königliche Familie zu sprechen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Hé bien, Sire Allen. Vous avez la langue bien pendue, dites-moi."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP10_ACT1_INTERLUDE2@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 422
L39_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "CHARLOTTE_ORDER_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "L"
L40_1 = "황족을 기망한 죄는 사형입니다, 전하."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "皇族を侮辱した罪は死刑に値します。殿下。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Deceiving against the crown is punishable by death, sir."
L39_1.m_Talk_ENG = L40_1
L40_1 = "欺罔皇室是要執行死刑嗎，殿下？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ทรยศราชบัลลังก์มีโทษถึงตายนะคะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Phản bội hoàng gia sẽ bị trừng trị bằng cái chết đó."
L39_1.m_Talk_VTN = L40_1
L40_1 = "欺罔皇族是要执行死刑吗，殿下?"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Das Hintergehen der königlichen Familie wird mit dem Tode bestraft, Eure Hoheit."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Insulter la famille royale est un crime passible de mort."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
