L42_1.m_Pos = "R"
L43_1 = "사실 그대로 말했을 뿐입니다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "事実を言ったまでです。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I was merely speaking the truth."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我只是實話實話而已。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ผมก็แค่พูดความจริงครับ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Tôi chỉ nói sự thật mà thôi."
L42_1.m_Talk_VTN = L43_1
L43_1 = "我只是实话实话而已。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich habe lediglich die Wahrheit gesagt."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Je ne disais que la vérité."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP10_ACT1_INTERLUDE2@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 422
L43_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L43_1.m_Pos = "R"
L44_1 = "지금도 막사에 계시면 제가 처리하고 오겠다고 한 지가 5분도 안 지났습니다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "今も、兵舎にいてくだされば私が対応して参りますと申し上げてから5分も経っていません。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Even now, it's been less than 5 minutes since I told you to stay in the barracks, Your Highness. I said I will take care of it."
L43_1.m_Talk_ENG = L44_1
L44_1 = "現在距離我請求殿下待在營帳裡，讓我來處理這件事，也才過去了不到5分鐘。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ขนาดตอนนี้ ผมบอกให้ฝ่าบาทอยู่ที่ป้อมได้ไม่ถึง 5 นาที ผมบอกว่าผมจะจัดการเอง"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ngay cả bây giờ, còn chưa đến 5 phút kể từ lúc tôi bảo Điện Hạ ở lại trong doanh trại. Tôi đã nói là tôi sẽ lo liệu mà."
L43_1.m_Talk_VTN = L44_1
L44_1 = "现在距离我请求殿下待在营帐里，让我来处理这件事，也才过去了不到5分钟。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Es ist gerade mal 5 Minuten her, seit ich Euch gesagt habe, Ihr sollt in der Kaserne bleiben, weil ich mich um die Angelegenheit kümmern werde, Eure Hoheit."
L43_1.m_Talk_DEU = L44_1
L44_1 = "D'ailleurs, ne vous avais-je pas demandé de rester à la caserne en attendant mon retour ? Il n'y a pas... 5 minutes de cela ?"
L43_1.m_Talk_FRA = L44_1
