L47_1 = "흥. 이 녀석에게 예법으로 지키라는 거냐."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ふん、こいつ相手に礼法を守れといういうのか。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Hmph. You expect him to act with decorum?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "哼，我從不期望一個平民舉止得體。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เฮอะ เจ้าหวังว่ามันจะมีสมบัติผู้ดีหรือไร?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Hmph. Ngài nghĩ tên nhóc sẽ biết cư xử đúng mực sao?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "哼，我从不期望一个平民举止得体。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Hmpf. Denkst du wirklich, dass sich dieser Bengel an die Regeln halten wird?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Hmph. Comme si ce prolétaire allait sagement vous écouter."
