L48_1 = "새 친구들까지 사귄 걸 보니 꽤 즐거운 산책이었나 보군."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "初めて見る顔ぶれまで連れてくるとは、相当楽しい散歩だったようだな。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "It must have been a fun little walk, seeing that you've made new friends already."
L47_1.m_Talk_ENG = L48_1
L48_1 = "你還交了新朋友，看來閒逛得很開心啊。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ไปเดินเล่นมาหน่อยคงสนุกดีสิท่า เห็นได้เพื่อนใหม่มาแล้วเสียด้วย"
L47_1.m_Talk_THA = L48_1
L48_1 = "Chắc cậu đi dạo vui lắm nhỉ, có vẻ như cậu đã có vài người bạn mới rồi."
L47_1.m_Talk_VTN = L48_1
L48_1 = "你还交了新朋友，看来在外面逛得很开心啊。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Es scheint ein recht angenehmer Spaziergang gewesen zu sein, wenn man bedenkt, dass du bereits neue Freunde gefunden hast."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je vois que tu t'es fait de nouveaux amis ? On dirait que tu t'amuses bien."
L47_1.m_Talk_FRA = L48_1
