L48_1.m_fTalkTime = 0.03
L49_1 = "はい。近辺の街で遭遇しました。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Yes, I ran into them in a nearby city."
L48_1.m_Talk_ENG = L49_1
L49_1 = "是的，他們是我在附近的城市遇到的。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ครับ ผมบังเอิญไปเจอพวกเขาแถวเมือง"
L48_1.m_Talk_THA = L49_1
L49_1 = "Đúng, tôi tình cờ gặp họ ở thành phố bên cạnh."
L48_1.m_Talk_VTN = L49_1
