L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L50_1.m_Pos = "C"
L51_1 = "전하, 외람된 말씀이오나 저들의 정체를 확신하기에는 아직 이릅니다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "殿下、恐れ入りますが、あの者たちの正体はまだ確信できません。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Forgive me, Your Highness. I believe that these so-called \"friends\" are not to be trusted yet."
L50_1.m_Talk_ENG = L51_1
L51_1 = "殿下，恕我冒昧，現在確定他們的真實身份還為時過早。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ขออภัยด้วยครับฝ่าบาท แต่ที่เรียกว่า \"เพื่อน\" นี่ ผมว่ายังไว้ใจไม่ได้ครับ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Xin lỗi, thưa Điện Hạ. Tôi tin rằng những kẻ được gọi là \"bạn bè'\" này chưa đáng tin."
L50_1.m_Talk_VTN = L51_1
L51_1 = "殿下，恕我冒昧，现在确定他们的真实身份还为时过早。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Verzeiht mir, Eure Hoheit. Ich glaube, dass man diesen sogenannten „Freunden“ noch nicht so ganz vertrauen kann."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Votre Altesse... Pardonnez mon impolitesse, mais je crois qu'il est encore un peu tôt pour faire confiance à ces nouveaux « amis »..."
L50_1.m_Talk_FRA = L51_1
