L2_1 = "EP10_ACT1_INTERLUDE2@51#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 51
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 422
L1_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L1_1.m_Pos = "C"
L2_1 = "마왕의 끄나풀일지도 모릅니다. 성녀를 불러 판별해 보시죠."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "魔王の手先かもしれません。聖女を呼んで確かめましょう。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Perhaps they were sent by the Demon Lord. I request to call over the Saintess and identify them."
L1_1.m_Talk_ENG = L2_1
L2_1 = "他們說不定是魔王的爪牙，還是叫聖女來判別一下為好。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "บางทีเจ้าแห่งดีม่อนอาจส่งพวกเขามา ผมขอให้เรียกนักบุญหญิงมาพิสูจน์ว่าพวกเขาเป็นใครครับ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Có lẽ chúng do Chúa Quỷ cử đến. Tôi yêu cầu triệu tập Thánh Nữ tới để nhận dạng họ."
L1_1.m_Talk_VTN = L2_1
L2_1 = "他们说不定是魔王的爪牙，还是叫圣女来判别一下为好。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Vielleicht wurden sie vom Dämonenfürsten geschickt. Ich bitte darum, die Heilige herzurufen, um sie überprüfen zu lassen."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Et s'ils avaient été envoyés par le Seigneur démon ? Nous devons demander à la Sainte de les examiner."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
