L5_1 = "EP10_ACT1_INTERLUDE2@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 422
L4_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "PRINCE_KNIGHT_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "R"
L5_1 = "그럴 필요 없다, 알렌."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "その必要はない。アレン。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "There won't be any need for that, Allen."
L4_1.m_Talk_ENG = L5_1
L5_1 = "沒那個必要，艾倫。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ไม่จำเป็นหรอก อัลเลน"
L4_1.m_Talk_THA = L5_1
L5_1 = "Không cần thiết đâu, Allen."
L4_1.m_Talk_VTN = L5_1
L5_1 = "没那个必要，艾伦。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Das wird nicht nötig sein, Allen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "C'est inutile, Allen."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP10_ACT1_INTERLUDE2@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 422
L5_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "PRINCE_KNIGHT_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "R"
L6_1 = "마왕의 수하라면 평민이 먼저 알아챘겠지. 예법에는 무지해도 감각만큼은 예리하니 말이다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "魔王の手下ならとっくにこの平民が気づいているだろう。礼法は知らなくても、勘だけは鋭いからな。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "If they belonged to the Demon Lord, the peasant would’ve noticed. Albeit his ignorance in etiquette, I believe his senses are trustworthy."
L5_1.m_Talk_ENG = L6_1
L6_1 = "是不是魔王的手下，平民會先認出來。雖然對禮法很無知，但敏銳的直覺還是具備的。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "หากพวกมันเป็นคนของเจ้าแห่งดีม่อน เจ้าไพร่นั่นย่อมสังเกตเห็นไปแล้ว แม้จะโง่เขลาเบามารยาท แต่สัมผัสของมันน่ะไว้ใจได้"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nếu chúng là tay sai của Chúa Quỷ, Nhóc Nông Dân đã biết rồi. Dù cư xử thô kệch, ta vẫn tin vào giác quan của nó."
L5_1.m_Talk_VTN = L6_1
L6_1 = "是不是魔王的手下，平民会先认出来。虽然对礼法很无知，但敏锐的直觉还是具备的。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wenn sie die Handlanger des Dämonenfürsten wären, hätte es der Bauernjunge bereits bemerkt. Trotz seiner Ignoranz bezüglich der Etikette sind seine Sinne dennoch messerscharf."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Si ces gens étaient des sbires du Seigneur démon, le prolétaire l'aurait remarqué. Il a beau ne pas connaître la politesse, je pense que nous pouvons nous fier à son instinct."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP10_ACT1_INTERLUDE2@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 422
L6_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "CHARLOTTE_ORDER_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "L"
L7_1 = "전투 중에 구원자의 감은 신뢰할 수 있습니다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "戦闘中の救世主の勘は信頼できます。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "The Savior's instincts in battle can be trusted."
L6_1.m_Talk_ENG = L7_1
L7_1 = "戰鬥期間可以相信救贖者的直覺。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "สัญชาตญาณในการต่อสู้ของพระผู้ไถ่นั้นไว้ใจได้ค่ะ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Bản năng của Đấng Cứu Thế trong trận chiến khá đáng tin."
L6_1.m_Talk_VTN = L7_1
L7_1 = "战斗期间可以相信救赎者的直觉。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Im Kampf kann man den Sinnen des Erlösers voll und ganz vertrauen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "L'instinct du Sauveur nous mènera vers la victoire au combat..."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP10_ACT1_INTERLUDE2@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 422
L7_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "CHARLOTTE_ORDER_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "L"
L8_1 = "평상시에는 못 미더운 구석뿐입니다만."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "普段はまったく頼り甲斐なんてありませんが。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "But not during everyday life."
L7_1.m_Talk_ENG = L8_1
L8_1 = "雖然平時不怎麼可靠。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แต่กับชีวิตประจำวันคือไม่ได้เลย"
L7_1.m_Talk_THA = L8_1
L8_1 = "Nhưng không phải trong cuộc sống hàng ngày."
L7_1.m_Talk_VTN = L8_1
L8_1 = "虽然平时不怎么可靠。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Nur nicht im Alltag."
L7_1.m_Talk_DEU = L8_1
L8_1 = "... mais pas dans la vie de tous les jours."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
