L10_1 = "EP10_ACT1_INTERLUDE2@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 422
L9_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_LAUGH"
L9_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L9_1.m_Pos = "C"
L10_1 = "미안해, 샬롯. 고치려는데 잘 안 되더라."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "ごめんね、シャーロット。直す努力はしているんだけど。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Sorry, Carlota. I'm trying to fix it, but it's not so easy."
L9_1.m_Talk_ENG = L10_1
L10_1 = "對不起，夏洛特。我想改的，但是改不好……"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ขอโทษนะคาร์โลตา ผมพยายามแก้แล้ว แต่ไม่ง่ายเลยล่ะ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Xin lỗi, Carlotta. Tôi đang cố gắng khắc phục, nhưng không dễ dàng."
L9_1.m_Talk_VTN = L10_1
L10_1 = "对不起，夏洛。我想改的，但是改不好……"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Tut mir leid, Carlota. Ich arbeite bereits daran, aber irgendwie klappt es nicht so richtig."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Désolé, Carlota. Je fais ce que je peux, mais ce n'est pas facile."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
