L12_1 = "EP10_ACT1_INTERLUDE2@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 422
L11_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "UNIT_SERIOUS"
L11_1.m_Face = L12_1
L12_1 = "FX_CUTSCEN_NOISE_RUSTLE_04"
L11_1.m_StartFXSoundName = L12_1
L12_1 = "PRINCE_KNIGHT_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "그래, 이 자들인가?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ああ、この者たちか？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "So, they must be the friends we've been talking about."
L11_1.m_Talk_ENG = L12_1
L12_1 = "嗯，是這些人嗎？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เช่นนั้น นี่คงเป็นเพื่อนๆ ที่เราพูดถึงกันอยู่สินะ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Vậy đây hẳn là đám bạn bè mà chúng ta đang nói đến."
L11_1.m_Talk_VTN = L12_1
L12_1 = "嗯，是这些人吗？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Das müssen also die Freunde sein, über die wir gerade gesprochen haben."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ce sont eux ? Tes nouveaux amis ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP10_ACT1_INTERLUDE2@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 422
L12_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_LAUGH"
L13_1 = "PRINCE_KNIGHT_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "환영한다, 제국의 신민들이여."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "よくぞ来た、帝国の臣民たちよ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Welcome, subjects of the Empire."
L12_1.m_Talk_ENG = L13_1
L13_1 = "歡迎你們，帝國的百姓。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ยินดีต้อนรับ เหล่าพสกนิกรของอาณาจักรเอ๋ย"
L12_1.m_Talk_THA = L13_1
L13_1 = "Xin hoan nghênh, những thần dân của đế chế."
L12_1.m_Talk_VTN = L13_1
L13_1 = "欢迎你们，帝国的臣民。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Willkommen, Untertanen des Imperiums."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Bienvenue, sujets de l'empire."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP10_ACT1_INTERLUDE2@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 422
L13_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "PRINCE_KNIGHT_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "마왕의 점령지에서는 풀 한 포기 찾기 어려웠겠지?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "魔王の占領地では、食べる草すらもなかっただろう。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I presume the Demon Lord's territory was not the most fertile."
L13_1.m_Talk_ENG = L14_1
L14_1 = "在寸草不生的魔王佔領區，很難品嘗到像樣的食物吧？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ข้าเดาว่าดินแดนของเจ้าแห่งดีม่อนคงมิได้อุดมสมบูรณ์เป็นที่ยิ่งสินะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi cho rằng lãnh thổ của Chúa Quỷ không phải là màu mỡ nhất."
L13_1.m_Talk_VTN = L14_1
L14_1 = "在寸草不生的魔王占领区，很难品尝到像样的食物了吧？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Es muss schwierig gewesen sein, im Territorium des Dämonenfürsten auch nur einen einzigen Grashalm zu finden, oder?"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Je suppose que les terres du Seigneur démon n'était pas des plus fertiles."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP10_ACT1_INTERLUDE2@64#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 64
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 422
L14_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "UNIT_PRIDE"
L14_1.m_Face = L15_1
L15_1 = "PRINCE_KNIGHT_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "따라와라. 마침 연회를 열어 병사들을 배불리 먹일 예정이었다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "ついてこい。ちょうど宴会を開いて兵士たちをたらふく食べさせようとしていたところだ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Come. A feast for the soldiers is about to take place."
L14_1.m_Talk_ENG = L15_1
L15_1 = "來吧。為士兵們準備的宴會就要開始了。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "มาสิ งานเลี้ยงของเหล่าทหารกำลังจะเริ่มแล้ว"
L14_1.m_Talk_THA = L15_1
L15_1 = "Đến đây, bữa tiệc cho những người lính sắp bắt đầu rồi."
L14_1.m_Talk_VTN = L15_1
L15_1 = "来吧。为士兵们准备的宴会就要开始了。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Folgt mir. Wir waren sowieso gerade dabei, ein Festmahl für die Soldaten herzurichten."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Que diriez-vous de vous sustenter ? Vous tombez bien, un banquet doit avoir lieu en l'honneur de nos soldats."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP10_ACT1_INTERLUDE2@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 422
L15_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "PRINCE_KNIGHT_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "함께 어울리면서 그간의 피로를 마음껏 풀도록."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "共に参加して、溜まった疲労をよくほぐすが良い。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Join us and rest your weary bodies."
L15_1.m_Talk_ENG = L16_1
L16_1 = "你們也一起加入，盡情消除一下這段時間累積的疲憊吧。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "มาร่วมดื่มกินกับเรา และพักร่างอันโรยแรงนั่นเสียเถิด"
L15_1.m_Talk_THA = L16_1
L16_1 = "Hãy tham gia cùng chúng ta và nghỉ ngơi chút nhé."
L15_1.m_Talk_VTN = L16_1
L16_1 = "你们也一起加入，尽情消除一下这段时间攒下的疲惫吧。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ihr könnt auch daran teilnehmen und euren erschöpften Körpern eine Pause genehmigen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Rejoignez-nous et reposez donc vos corps fatigués."
L15_1.m_Talk_FRA = L16_1
