L19_1 = "UNIT_SURPRISE"
L18_1.m_Face = L19_1
L19_1 = "YOOMINA_FENRIR_NEXT_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "L"
L19_1 = "분위기가……."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ここの雰囲気は……"
L18_1.m_Talk_JPN = L19_1
L19_1 = "The atmosphere here..."
L18_1.m_Talk_ENG = L19_1
L19_1 = "氣氛……"
L18_1.m_Talk_TWN = L19_1
L19_1 = "บรรยากาศที่นี่มัน..."
L18_1.m_Talk_THA = L19_1
L19_1 = "Bầu không khí ở đây..."
L18_1.m_Talk_VTN = L19_1
L19_1 = "氛围……"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Die Atmosphäre hier ..."
L18_1.m_Talk_DEU = L19_1
L19_1 = "L'ambiance ici, elle est..."
L18_1.m_Talk_FRA = L19_1
