L20_1 = "EP10_ACT1_INTERLUDE2@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 422
L19_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L20_1 = "많이 다르군요. 저희가 겪었던 것들과."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "大違いですね。僕たちが経験した出来事とは。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "It's drastically different from what we've gone through."
L19_1.m_Talk_ENG = L20_1
L20_1 = "很不一樣啊，和我們經歷過的相比。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "คนละเรื่องกับที่เราเจอมาเลยเนอะ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Nó hoàn toàn khác với những gì chúng ta đã trải qua."
L19_1.m_Talk_VTN = L20_1
L20_1 = "很不一样啊，和我们经历过的相比。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Sie unterscheidet sich drastisch von dem, was wir bisher durchgemacht haben."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Différente. Ça tranche radicalement avec tout ce qu'on a vécu jusqu'à maintenant."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
