L22_1 = "EP10_ACT1_INTERLUDE2@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 422
L21_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "SEO_YOON_ALT_CA_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "글쎄. 선배 말대로 환각의 일종이라면, 과거의 기억이라도 적당히 윤색되지 않았을까?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "さあね。先輩の言う通りこれも幻覚なら、過去の記憶とはいえ、都合よく美化されているんじゃないかしら？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Hmm. If this really is a hallucination like you mentioned, maybe the memories were polished up a bit."
L21_1.m_Talk_ENG = L22_1
L22_1 = "這個嘛，如果真像你所說的那樣，這是一種幻覺，那過去的記憶也會被適當地美化吧？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อืม ถ้านี่เป็นภาพหลอนจริงอย่างที่ว่า สงสัยจะปรุงแต่งความทรงจำให้ดีงามขึ้นนิดหน่อยเลย"
L21_1.m_Talk_THA = L22_1
L22_1 = "Hmm. Nếu đây thực sự là ảo giác như cậu nói, có lẽ ký ức của cậu đã được đánh bóng đôi chút."
L21_1.m_Talk_VTN = L22_1
L22_1 = "这个嘛，如果真像你所说的那样，这是一种幻觉，那过去的记忆也会被适当地美化吧？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Nun ja. Wenn es sich wirklich um eine Halluzination handelt, wie du gemeint hast, wurden die Erinnerungen vielleicht ein wenig aufgehübscht."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Hmm. Si nous sommes vraiment dans une illusion, peut-être que les souvenirs de Ray ont été un peu embellis."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP10_ACT1_INTERLUDE2@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 422
L22_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_DESPAIR"
L23_1 = "SEO_YOON_ALT_CA_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "또 모르지. 우리 사기를 꺾기 위한 수작일 수도."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "そして、私たちの士気を下げるためにこういうふうに見せているのかもしれない。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Or maybe it’s a strategy to lower our guards."
L22_1.m_Talk_ENG = L23_1
L23_1 = "也說不定，這只是讓我們放鬆警惕的手段。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "หรืออาจเป็นแผนให้เราชะล่าใจก็ได้"
L22_1.m_Talk_THA = L23_1
L23_1 = "Hoặc có thể đó là một chiến lược để hạ thấp cảnh giác của chúng ta."
L22_1.m_Talk_VTN = L23_1
L23_1 = "也说不定，这只是让我们放松警惕的手段。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wer weiß. Es könnte ein Trick sein, um uns abzulenken."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ou alors c'est une ruse pour que nous baissions notre garde."
L22_1.m_Talk_FRA = L23_1
