L27_1 = "EP10_ACT1_INTERLUDE2@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 422
L26_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L26_1.m_bWaitClick = true
