L27_1 = "YOOMINA_FENRIR_NEXT_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "L"
L27_1 = "레이 선배는 그럴 사람 같진 않았어."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "レイ先輩はそんな人には見えなかったよ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Ray didn't seem like someone who would do such a thing."
L26_1.m_Talk_ENG = L27_1
L27_1 = "但雷伊前輩不像那種人。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เรย์ดูไม่ใช่คนที่จะทำอะไรแบบนั้นนะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Ray có vẻ không giống người sẽ làm chuyện như thế."
L26_1.m_Talk_VTN = L27_1
L27_1 = "但雷伊前辈不像那种人。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ray schien nicht jemand zu sein, der so etwas tun würde."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Je ne crois pas que Ray aurait recours à une telle fourberie."
L26_1.m_Talk_FRA = L27_1
