L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 422
L28_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_LAUGH"
L29_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "R"
L29_1 = "지금은 저 분들을 뒤따라가 보죠. 뭔가 더 확인할 수 있을지도 모르잖아요?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "今はあの方々について行ってみましょう。もっと何か確認できるかもしれませんから。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "For now, let's all follow him. We might get more information."
L28_1.m_Talk_ENG = L29_1
L29_1 = "現在先跟著他們去吧。說不定還能進一步確認一下呢？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ตอนนี้ก็ตามเขาไปก่อนแล้วกันครับ เราอาจได้ข้อมูลเพิ่มก็ได้"
L28_1.m_Talk_THA = L29_1
L29_1 = "Thôi, cứ đi theo cậu ta đã. Chúng ta sẽ sớm có thêm thông tin thôi."
L28_1.m_Talk_VTN = L29_1
L29_1 = "现在先跟着他们去吧。说不定还能进一步确认一下呢？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Wir sollten ihm vorerst folgen. Möglicherweise erhalten wir weitere nützliche Informationen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Contentons-nous de les suivre pour le moment. On pourra peut-être apprendre quelque chose."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
