L31_1[L32_1] = 15
L32_1 = "출정을 앞둔 마지막 날이다!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "今日は出征を控えた最後の日だ！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Tomorrow is the day we leave for battle!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "今天是出征前的最後一天！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "พรุ่งนี้เราจะออกศึก!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ngày mai là ngày chúng ta ra trận!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "今天是出征前的最后一天！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Morgen ist der Tag, an dem wir zur Schlacht aufbrechen!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Demain, nous partons enfin au combat !"
L31_1.m_Talk_FRA = L32_1
