L32_1.m_CharStrID = "KNIGHT_NPC_CHIEF_NULL"
L32_1.m_Pos = "C"
L33_1 = "구원자님과 황태자 전하, 성녀님까지 모두 한 자리에 모이셨다!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "救世主様と皇太子殿下、聖女様がこの場にいらっしゃる！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "The Savior, His Highness, and the Saintess have all come here to celebrate!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "救贖者大人，皇太子殿下，還有聖女全都來了！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "พระผู้ไถ่ ฝ่าบาท นักบุญหญิง ล้วนมาเฉลิมฉลองกันที่นี่!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Đấng Cứu Thế, Thánh Nữ và Điện Hạ đều tới đây để chúc mừng!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "救赎者，皇太子殿下，还有圣女全都来了！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Der Erlöser, Seine Hoheit und die Heilige sind alle hierher gekommen, um mit uns zu feiern!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Le Sauveur, Son Altesse et la Sainte sont venus célébrer le grand départ avec nous !"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
