L34_1 = "m_Crash"
L33_1[L34_1] = 20
L34_1 = "두려움은 잊어라! 오늘은 모두 배불리 먹고 즐기자!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "恐れる気持ちは忘れよ！　今日は皆、たらふく食べて楽しむんだ！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Fear shall be forgotten! Tonight, we feast!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "忘記恐懼！今天大家盡情地吃飽享受吧！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ความกลัวจักถูกหลงลืมไป! คืนนี้เราจะฉลองกัน!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Hãy bỏ nỗi sợ hãi lại phía sau! Tối nay, chúng ta sẽ tiệc tùng cho thỏa thích."
L33_1.m_Talk_VTN = L34_1
L34_1 = "忘记恐惧！今天大家尽情地吃饱享受吧！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Vergesst eure Ängste! Heute Abend wird gefeiert!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Oubliez la peur et ce soir, buvez !"
L33_1.m_Talk_FRA = L34_1
