L38_1 = "그래? 평민과 검을 겨뤘다고?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "そうか？　平民と剣を交えたと？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Oh? You say you've fought against the peasant?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "是嗎？和平民比劍了？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "โอ้? เจ้าว่าเจ้าสู้กับเจ้าไพร่นั่นรึ?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Ồ? Cô nói cô đã đánh nhau với Tên Nhóc Nông Dân đó sao?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "是吗？和平民比剑了？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Oh? Du hast also mit dem Schwert gegen den Bauernjungen gekämpft?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Oh ? Vous vous êtes battu avec le prolétaire ?"
L37_1.m_Talk_FRA = L38_1
