L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "L"
L39_1 = "공격은 성공했나?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "攻撃は通用したか？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Were any of your attacks effective?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "有打中嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "โจมตีอะไรได้ผลบ้างหรือไม่คะ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Có đòn tấn công nào của cô hiệu quả không?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "有打中吗？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Waren deine Angriffe erfolgreich?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Et vous avez réussi à le toucher ?"
L38_1.m_Talk_FRA = L39_1
