L41_1 = "m_Crash"
L40_1[L41_1] = 15
L41_1 = "아, 아니. 전부 막히긴 했는데……."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "い、いや。全部防がれちゃったけど……"
L40_1.m_Talk_JPN = L41_1
L41_1 = "N-no. He blocked them all..."
L40_1.m_Talk_ENG = L41_1
L41_1 = "沒，沒有，全被擋下了……"
L40_1.m_Talk_TWN = L41_1
L41_1 = "มะ-ไม่ได้เลย เขากันได้หมดเลยล่ะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "K-không. Anh ấy đã chặn đứng tất cả..."
L40_1.m_Talk_VTN = L41_1
L41_1 = "没、没有，全被挡下了……"
L40_1.m_Talk_SCN = L41_1
L41_1 = "N-nein. Er konnte sie alle abwehren ..."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Non... il a bloqué toutes nos attaques..."
L40_1.m_Talk_FRA = L41_1
