L41_1.m_Pos = "C"
L42_1 = "그렇다면 내 승리군."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ならば私の勝ちだな。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I am the victor here, then."
L41_1.m_Talk_ENG = L42_1
L42_1 = "那就是我贏了。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เช่นนั้นข้าก็เป็นผู้ชนะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Thế thì tôi là người chiến thắng ở đây rồi."
L41_1.m_Talk_VTN = L42_1
L42_1 = "那就是我赢了。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Dann bin ich hier die Siegerin."
L41_1.m_Talk_DEU = L42_1
L42_1 = "On dirait que c'est moi qui l'emporte, alors."
