L44_1[2] = L46_1
L42_1[L43_1] = L44_1
L43_1 = "최근 대련에서 무려 옷깃을 베는 데 성공했으니까."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "最近の模擬対戦では、なんと襟元をかすめるのに成功したから。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I succeeded in cutting off part of his sleeves in our last duel."
L42_1.m_Talk_ENG = L43_1
L43_1 = "在最近的對練中我成功地割破了他的衣領。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ดวลกันคราวก่อนข้าฟันแขนเสื้อมันขาด"
L42_1.m_Talk_THA = L43_1
L43_1 = "Trong trận đấu lần cuối thì tôi đã thành công cắt được một phần tay áo của cậu ta."
L42_1.m_Talk_VTN = L43_1
L43_1 = "在最近的对练中我成功地割破了他的衣领。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Bei unserem letzten Duell gelang es mir, einen Teil seiner Ärmel abzuschneiden."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Lors de notre dernier duel, j'ai réussi à trancher la manche de sa veste."
L42_1.m_Talk_FRA = L43_1
