L45_1 = "EP10_ACT1_INTERLUDE2@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 422
L44_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "UNIT_SURPRISE"
L44_1.m_Face = L45_1
L45_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "R_M_I"
L45_1 = "호오, 흥미롭네요. 어떻게 해야 그런 대단한 위업을 세울 수 있는 거죠?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "へぇ……興味深いですね。どうすればそのような凄まじい偉業が成せるんですか？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Oh, interesting. How did you achieve such greatness?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "哈哈，有意思。是怎麼完成如此偉大的壯舉的呢？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "โอ๊ะ น่าสนใจนะครับ ทำยังไงถึงเก่งขนาดนั้นครับ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Oh! Thật thú vị. Sao cô làm được điều vĩ đại đó vậy?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "哈哈，有意思。是怎么完成如此伟大的壮举的呢？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Oh, wie interessant. Wie ist es dir gelungen, solch eine unglaubliche Leistung zu vollbringen?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Oh, intéressant. Et comment avez-vous fait pour réussir un tel exploit ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP10_ACT1_INTERLUDE2@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 422
L45_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_LAUGH"
L46_1 = "CHARLOTTE_ORDER_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "L"
L46_1 = "늑대처럼 죽어도 동료가 뒤를 맡아 줄 거라는 마음가짐으로 달려들면 된다. 그것뿐이야."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "狼のように、たとえ死んでも仲間が後を引き受けてくれるという気持ちで挑む、それだけだ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "All it takes is trust. Trust that even if I die like the Wolf, my comrades will take care of the rest."
L45_1.m_Talk_ENG = L46_1
L46_1 = "像狼一樣，抱著哪怕自己死掉，同伴也會負責後方的信念撲上去就行了。僅此而已。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แค่ต้องเชื่อใจค่ะ เชื่อใจกันว่าต่อให้ข้าตายเหมือนหมาป่า เหล่าสหายของเราก็จะจัดการที่เหลือให้"
L45_1.m_Talk_THA = L46_1
L46_1 = "Chỉ cần niềm tin thôi. Niềm tin rằng ngay cả khi tôi chết như Con Sói, đồng đội của tôi cũng sẽ lo liệu phần còn lại."
L45_1.m_Talk_VTN = L46_1
L46_1 = "像狼一样，抱着哪怕自己死掉，同伴也会负责后方的信念扑上去就行了。仅此而已。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Alles, was man braucht, ist Vertrauen. Ich vertraue darauf, dass meine Kameraden sich um den Rest kümmern werden, selbst wenn ich wie der Wolf sterbe sollte."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Tout ce ce qu'il faut, c'est d'un peu de confiance. Et je sais que même si je meurs comme cette louve, mes camarades s'occuperont du reste."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP10_ACT1_INTERLUDE2@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 422
L46_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "R"
L47_1 = "구원자님에게도 그런 약점이 있었군요. 굉장한 정보네요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "救世主様にもそのような弱点が。すごい情報ですね。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I didn't know the mighty Savior had weaknesses... this is fascinating news."
L46_1.m_Talk_ENG = L47_1
L47_1 = "原來救贖者還有這樣的弱點。這個情報很了不得啊。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ไม่ยักรู้เลยนะครับว่าพระผู้ไถ่ผู้ยิ่งใหญ่จะมีจุดอ่อนด้วย... เป็นข่าวสารที่น่าทึ่งมากครับ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tôi không biết Đấng Cứu Thế quyền năng lại có điểm yếu đấy... quả là một tin sốt dẻo."
L46_1.m_Talk_VTN = L47_1
L47_1 = "原来救赎者还有这样的弱点。这个情报很了不得啊。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich wusste nicht, dass auch der Erlöser eine Schwachstelle hat. Das ist eine äußerst interessante Information."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Alors même le Sauveur a des points faibles... c'est une information précieuse."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
