L49_1 = "EP10_ACT1_INTERLUDE2@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 422
L48_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "UNIT_HATE"
L48_1.m_Face = L49_1
L49_1 = "SEO_YOON_ALT_CA_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "……정보라기에는 영 시원치 않은데, 선배."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "……本当に使える情報なの？　先輩。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "...It's too trivial to be called news, Shiyoon."
L48_1.m_Talk_ENG = L49_1
L49_1 = "……說是情報，還不如說是瑣事呢，前輩。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "...มันจิ๊บจ๊อยเกินจะเรียกว่าข่าวสารนะชิยุน"
L48_1.m_Talk_THA = L49_1
L49_1 = "...Cái đó chẳng đáng được gọi là tin tức, Shiyoon ạ."
L48_1.m_Talk_VTN = L49_1
L49_1 = "……说是情报，还不如说是琐事呢，前辈。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "... Das hört sich nicht wirklich nach einer brauchbaren Information an, Shiyoon."
L48_1.m_Talk_DEU = L49_1
L49_1 = "... Franchement, tu parles d'une info."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP10_ACT1_INTERLUDE2@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 422
L49_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_Face = "UNIT_LAUGH"
L50_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "하하, 서윤 양. 지금은 차분하게 지켜보세요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ハハ、まぁシズカさん、今は落ち着いて待ちましょう。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Ha ha. Just watch for now, Seo Yoon."
L49_1.m_Talk_ENG = L50_1
L50_1 = "哈哈，先靜觀其變吧，徐芸小姐。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฮ่าฮ่า ดูไปก่อนน่า ซอ ยุน"
L49_1.m_Talk_THA = L50_1
L50_1 = "Ha ha. Cứ chờ xem, Seo Yoon."
L49_1.m_Talk_VTN = L50_1
L50_1 = "哈哈，先静观其变吧，徐芸小姐。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Haha. Schau einfach nur in Ruhe zu, Seo Yoon."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Ha ha. Contentons-nous d'observer pour le moment, Yoon."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP10_ACT1_INTERLUDE2@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 422
L50_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "저쪽도 그걸 원한다면, 너무 조바심 낼 필요는 없지 않을까요?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "向こうも望んでいるものが同じなのであれば、あまり焦る必要はないでしょう？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "If it's what they want, there's no need to rush ourselves."
L50_1.m_Talk_ENG = L51_1
L51_1 = "如果這就是對方想要的，我們何必著急呢？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ก็ถ้าพวกเขาจะเอาแบบนี้ เราก็ไม่ต้องรีบร้อนนี่"
L50_1.m_Talk_THA = L51_1
L51_1 = "Nếu đó là điều họ muốn, chúng ta không cần phải vội."
L50_1.m_Talk_VTN = L51_1
L51_1 = "如果这就是对方想要的，我们何必着急呢？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Wenn es das ist, was sie wollen, besteht kein Grund zur Eile."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Notre ennemi a l'air de vouloir faire de même, alors inutile de se précipiter."
L50_1.m_Talk_FRA = L51_1
