L4_1 = "EP10_ACT1_INTERLUDE2@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 422
L3_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "PRINCE_KNIGHT_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "L"
L4_1 = "어떡할 거냐, 평민. 네가 지난번 대련에서 적당히 봐준 뒤로 샬롯이 줄곧 저 상태다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "どうしてくれる、平民。貴様がこの前の模擬対戦で手を抜いてからというもの、シャーロットがずっとあの調子だ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "What will you do now, peasant? Carlota has been like that ever since you've gone easy on her."
L3_1.m_Talk_ENG = L4_1
L4_1 = "你要如何應對呢，平民。自從上次你在對練中手下留情後，夏洛特就是那個樣子了。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แล้วตอนนี้จะทำยังไงดีเล่า เจ้าไพร่? คาร์โลตาเป็นแบบนั้นตั้งแต่เจ้าออมมือให้แล้วนะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Cậu sẽ làm gì hả Nhóc Nông Dân? Carlota cứ như vậy kể từ khi cậu dễ dãi với cô ta."
L3_1.m_Talk_VTN = L4_1
L4_1 = "你要如何应对呢，平民。自从上次你在对练中手下留情后，夏洛就是那个样子了。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Was wirst du jetzt tun, Bauernjunge? Carlota verhält sich so, seitdem du so sanft ihr gegenüber geworden bist."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Que comptes-tu faire ? Carlota trépigne depuis que tu l'as ridiculisée la dernière fois."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP10_ACT1_INTERLUDE2@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 422
L4_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L4_1.m_Pos = "R"
L5_1 = "제가 누굴 봐준다거나 할 실력이 아니라는 건 전하께서도 아시잖아요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "僕の実力が誰かに手を抜くことができるようなものじゃないこと、殿下もご存知ではないですか。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "You know I'm not good enough to go easy on others, Your Highness."
L4_1.m_Talk_ENG = L5_1
L5_1 = "我沒什麼實力對別人手下留情，殿下也知道不是嘛。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ท่านก็รู้นี่ครับฝ่าบาท ว่าผมไม่เก่งพอจะไปออมมือให้ใคร"
L4_1.m_Talk_THA = L5_1
L5_1 = "Ngài biết tôi không đủ tốt để dễ dãi với người khác mà, Điện Hạ."
L4_1.m_Talk_VTN = L5_1
L5_1 = "我没什么实力对别人手下留情，殿下也知道不是嘛。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Eure Hoheit weiß, dass ich nicht geschickt genug bin, um jemanden absichtlich zu schonen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Allons, Votre Altesse. Vous savez bien que je ne suis pas doué au point de pouvoir ridiculiser qui que ce soit."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP10_ACT1_INTERLUDE2@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 422
L5_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L5_1.m_Pos = "R"
L6_1 = "샬롯 경이 노력한 만큼 성과를 얻은 거라고 생각합니다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "シャーロットが努力した分、結果がついてきただけです。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I like to think that Dame Carlota achieved this through her own efforts."
L5_1.m_Talk_ENG = L6_1
L6_1 = "我認為是夏洛特卿的努力取得了相應的成果。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ผมอยากคิดว่าท่านหญิงคาร์โลตาสำเร็จมาได้ก็ด้วยความพยายามของตัวเองมากกว่า"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tôi thích nghĩ rằng Tiểu Thư Carlota đã làm được điều này nhờ sự nỗ lực của chính cô ấy."
L5_1.m_Talk_VTN = L6_1
L6_1 = "我认为是夏洛爵士的努力取得了相应的成果。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich denke, dass Gräfin Martinez dies durch ihre eigenen Bemühungen erreicht hat."
L5_1.m_Talk_DEU = L6_1
L6_1 = "La comtesse Martinez a obtenu des résultats à la hauteur de ses compétences, voilà tout."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP10_ACT1_INTERLUDE2@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 422
L6_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "UNIT_PRIDE"
L6_1.m_Face = L7_1
L7_1 = "PRINCE_KNIGHT_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "L"
L7_1 = "구원자가 된 뒤로 입담만 늘었군. 내 앞에서 겸손 따위 떨지 마라."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "救世主になってから、口ばかり達者になったものだ。私の前で謙遜など必要ない。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "You've become quite cunning after earning the title of \"Savior\". Do not assume that you can fool me too."
L6_1.m_Talk_ENG = L7_1
L7_1 = "哼，成為救贖者以後，你的口才倒是長進了不少。少在我面前自謙。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "พอได้ฉายา \"พระผู้ไถ่\" แล้วเหลี่ยมจัดขึ้นนะเจ้าน่ะ อย่าหวังว่าจะหลอกข้าได้อีกคนไปเชียว"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cậu cũng khôn lỏi ra sau khi kiếm được danh hiệu \"Đấng Cứu Thế\" đấy nhứ. Đừng cho rằng cậu cũng có thể lừa ta."
L6_1.m_Talk_VTN = L7_1
L7_1 = "哼，成为救赎者以后，你的口才倒是长进了不少。少在我面前自谦。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Seitdem du zum Erlöser ernannt wurdest, bist du viel gesprächiger geworden. Kein Grund, so bescheiden zu sein."
L6_1.m_Talk_DEU = L7_1
L7_1 = "On dirait que ton nouveau titre te monte à la tête, Sauveur. Mais je ne suis pas né de la dernière pluie, figure-toi."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
