L8_1.m_fWaitTime = 0
L9_1 = "HOLY_KNIGHT_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L9_1 = "하지만 구원자님과 겨뤘다면 실력은 증명이 된 셈 아닌가요?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ですが、救世主様とやり合ったのなら、すでに実力は証明されたのでは？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "But hasn’t she proved her worth by going against the Savior?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "如果和救贖者大人比試過了，不就相當於是證明實力了嗎？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แต่นางก็ได้พิสูจน์แล้วใช่หรือไม่คะ ว่าตนคู่ควรจะประมือกับพระผู้ไถ่?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Nhưng chẳng phải cô ấy đã chứng minh giá trị của mình bằng cách đấu với Đấng Cứu Thế sao ạ?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "如果和救赎者大人比试过了，不就相当于是证明实力了吗？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Aber hat sie ihre Fähigkeit nicht dadurch unter Beweis gestellt, dass sie gegen den Erlöser angetreten ist?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Mais Carlota n'a-t-elle pas prouvé sa valeur en prenant le courage d'affronter le Sauveur ?"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP10_ACT1_INTERLUDE2@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 422
L9_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "HOLY_KNIGHT_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "마왕과의 전투에서 어지간한 실력자들은 방해만 될 뿐이겠죠."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "魔王との戦いでは、よっぽどの実力者でない限り、足手まといになるだけです。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Any other mediocre swordsman wouldn't stand a chance against the Demon Lord."
L9_1.m_Talk_ENG = L10_1
L10_1 = "在與魔王的戰鬥中，實力一般的人只會礙事罷了。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เพราะหากเป็นนักดาบดาดๆ ก็คงไม่มีปัญญาจะหาชีวิตรอดจากเจ้าแห่งดีม่อน"
L9_1.m_Talk_THA = L10_1
L10_1 = "Bất kỳ kiếm sĩ tầm thường nào khác sẽ chẳng có cơ may nào khi đấu với Chúa Quỷ."
L9_1.m_Talk_VTN = L10_1
L10_1 = "在与魔王的战斗中，实力一般的人只会碍事罢了。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Jeder andere mittelmäßige Schwertkämpfer hätte gegen den Dämonenfürsten nicht die geringste Chance."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Contre un Seigneur démon, elle vaudra mieux que tous ces épéistes de pacotille..."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "EP10_ACT1_INTERLUDE2@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 422
L10_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "HOLY_KNIGHT_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "이대로 기사단에 합류시키는 건 어떨까요?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "このまま騎士団に合流させてはいかがでしょうか？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Why don't we make her join the Knights of Redemption?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "就這樣讓她加入騎士團怎麼樣？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ไยเราไม่ให้นางเข้าร่วมกับคณะอัศวินไถ่ถอนบาปเล่า?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tại sao chúng ta không để cô ấy gia nhập Hiệp Sĩ Chuộc Tội chứ?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "就这样让她加入骑士团怎么样？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Warum zwingen wir sie nicht dazu, sich den Rittern der Erlösung anzuschließen?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Pourquoi ne rejoindrait-elle pas les Chevaliers de la Rédemption ?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP10_ACT1_INTERLUDE2@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 422
L11_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_LAUGH"
L12_1 = "PRINCE_KNIGHT_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "하하, 실력이라고? 그대가 할 소리는 아니지 않나?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "はは、実力だと？　貴様が言うことではないと思うが。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Ha ha, her worth? That's not for you to say."
L11_1.m_Talk_ENG = L12_1
L12_1 = "哈哈，實力？這不是你該說的話吧？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฮ่าฮ่า นางคู่ควรเหรอ? แต่ปากเจ้าไม่คู่ควรกล่าวคำนั้นนะ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Ha ha, giá trị của cô ấy ư? Cái đó không phải thứ để cô nói đâu."
L11_1.m_Talk_VTN = L12_1
L12_1 = "哈哈，实力？这不是你该说的话吧？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Haha, ihre Fähigkeiten unter Beweis gestellt? Das hast nicht du zu beurteilen."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Prouvé sa valeur, vraiment ? Et qui es-tu pour dire ça ?"
L11_1.m_Talk_FRA = L12_1
