L13_1 = "EP10_ACT1_INTERLUDE2@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 422
L12_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "UNIT_HATE"
L12_1.m_Face = L13_1
L13_1 = "HOLY_KNIGHT_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "구원자님께 드린 말씀이었습니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "私は救世主様に申し上げています。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I was talking to the Savior."
L12_1.m_Talk_ENG = L13_1
L13_1 = "我是在和救贖者大人說話。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ข้ากำลังพูดกับพระผู้ไถ่ค่ะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tôi đang nói chuyện với Đấng Cứu Thế."
L12_1.m_Talk_VTN = L13_1
L13_1 = "我是在和救赎者大人说话。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich habe mit dem Erlöser gesprochen."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Je parlais au Sauveur."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP10_ACT1_INTERLUDE2@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 422
L13_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "HOLY_KNIGHT_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "전하께서는 저 방탕한 축제에나 끼어 계시죠."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "殿下はあのお祭り騒ぎに参加された方がよろしいのでは？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "You should go ahead and enjoy that lousy feast, your dear Highness."
L13_1.m_Talk_ENG = L14_1
L14_1 = "您現在不是應該在那個縱情享樂的慶典上嗎，殿下？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ส่วนท่านก็ควรไปร่วมงานเลี้ยงน่าเดียดฉันท์นั่นเสียนะคะ ฝ่าพระบาทที่เคารพ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Ngài nên tiếp tục tận hưởng bữa tiệc ồn ào đi, thưa Điện Hạ thân mến."
L13_1.m_Talk_VTN = L14_1
L14_1 = "您现在不是应该在那个浪荡的庆典上吗，殿下？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ihr solltet gehen und dieses ausschweifende Fest genießen, Eure Hoheit."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Vous feriez mieux d'aller profiter du banquet avant qu'il ne soit trop tard, Votre Altesse."
L13_1.m_Talk_FRA = L14_1
