L17_1 = "EP10_ACT1_INTERLUDE2@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 422
L16_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_LAUGH"
L17_1 = "PRINCE_KNIGHT_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "L"
L17_1 = "술도 없는 자리에 끼어서 무엇하겠나. 병사들 음식만 축낼 뿐이지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "酒もないところに参加してどうする。兵士たちの分の料理を減らしてしまうだけだ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "What would one do without a drink to enjoy? All I can do there is take away the soldier’s food."
L16_1.m_Talk_ENG = L17_1
L17_1 = "沒有酒的宴會？還是把食物讓給士兵們好了。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "คนเราจะทำอะไรได้เล่าหากไม่มีเหล้าให้สุขโสมนัส? ข้าก็มีแต่จะไปแย่งอาหารพวกทหารเสียเปล่า"
L16_1.m_Talk_THA = L17_1
L17_1 = "Người ta sẽ làm gì nếu không có rượu để thưởng thức chứ? Ta thì chỉ lấy được đồ ăn của binh sĩ thôi."
L16_1.m_Talk_VTN = L17_1
L17_1 = "一个没有酒的宴会？那还是把食物让给士兵们好了。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Was soll ich denn an einem Ort, an dem es keinen Alkohol gibt? Ich würde lediglich das Essen der Soldaten verschwenden."
L16_1.m_Talk_DEU = L17_1
L17_1 = "À quoi bon ? Nous n'avons rien à boire. Je ne vais tout de même pas ôter le pain de la bouche de mes soldats, si ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
