L20_1 = "EP10_ACT1_INTERLUDE2@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 422
L19_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L19_1.m_Pos = "R"
L20_1 = "저번에 여쭤 봤던 용병단 소식은 혹시 들어왔습니까?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "以前お伺いした傭兵隊に関してですが、何か情報は入ってきましたか？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Any news from the Mercenaries I asked before?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "上次我問您的傭兵隊有消息了嗎？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "มีข่าวเรื่องทหารรับจ้างที่ผมเคยถามไปบ้างมั้ยครับ?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Có tin tức gì từ Lính Đánh Thuê mà tôi đã hỏi lúc trước không?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "上次我问您的佣兵队有消息了吗？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Gibt es irgendwelche Neuigkeiten von den Söldnern, nach denen ich mich letztes Mal erkundigt habe?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Avez-vous des nouvelles des mercenaires dont je vous ai parlé plus tôt ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP10_ACT1_INTERLUDE2@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 422
L20_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_IDLE"
L21_1 = "PRINCE_KNIGHT_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "L"
L21_1 = "나를 전령 취급하는 녀석은 네가 유일할 거다, 평민."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "私を伝令扱いするヤツは貴様だけだ、平民。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I believe that you are the only living soul to ever treat me as a messenger, peasant."
L20_1.m_Talk_ENG = L21_1
L21_1 = "你是唯一一個拿我當信使的人，平民。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ข้าเชื่อนักว่า เจ้าเป็นมนุษย์เพียงคนเดียวที่กล้าทำราวข้าเป็นพลนำสารนะ เจ้าไพร่"
L20_1.m_Talk_THA = L21_1
L21_1 = "Ta tin cậu là linh hồn còn sống duy nhất từng coi ta là người đưa tin, Nhóc Nông Dân à."
L20_1.m_Talk_VTN = L21_1
L21_1 = "你是唯一一个拿我当传话筒的人，平民。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Du bist höchstwahrscheinlich der Einzige, der mich wie einen Boten behandelt, Bauernjunge."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Tu dois bien être le seul dans ce pays qui me traite comme un messager, prolétaire."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP10_ACT1_INTERLUDE2@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 422
L21_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L21_1.m_Pos = "R"
L22_1 = "불편하셨다면 죄송합니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "お気に障ったら、申し訳ありません。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Apologies if I made you uncomfortable."
L21_1.m_Talk_ENG = L22_1
L22_1 = "如果給您添麻煩了，那我很抱歉。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ขออภัยด้วยนะครับที่ทำให้ท่านขัดข้องใจ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Xin lỗi nếu tôi làm ngài khó chịu."
L21_1.m_Talk_VTN = L22_1
L22_1 = "如果给您添麻烦了，那我很抱歉。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Es tut mir leid, wenn ich Euch damit Unbehagen bereitet habe."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Pardon si mes propos vous ont vexé."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP10_ACT1_INTERLUDE2@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 422
L22_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "UNIT_PRIDE"
L22_1.m_Face = L23_1
L23_1 = "PRINCE_KNIGHT_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "L"
L23_1 = "아니. 됐다. 적당히 일러 두려고 했으니."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "いや、いい。どうせ話しておこうと思っていた。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Keep your apologies. I was meaning to inform you anyway."
L22_1.m_Talk_ENG = L23_1
L23_1 = "不，算了，我本來就想找個適當的時機提醒你。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เก็บคำขอโทษไว้อมเล่นเถอะ ข้าไม่ได้คิดจะบอกเจ้าอยู่แล้ว"
L22_1.m_Talk_THA = L23_1
L23_1 = "Thôi bỏ đi. Đằng nào ta cũng định nói với cậu."
L22_1.m_Talk_VTN = L23_1
L23_1 = "不，算了，我本来就想找个适当的时机提醒你。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Schon gut. Das kannst du dir sparen. Ich wollte dich sowieso informieren."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Garde tes excuses pour toi. Je comptais t'en parler de toute façon."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
