L25_1 = "EP10_ACT1_INTERLUDE2@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 422
L24_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_IDLE"
L25_1 = "PRINCE_KNIGHT_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "결론부터 말해 주지. 펜릴 용병단은 포기해라."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "結論から言おう。フェンリル傭兵隊は諦めろ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Let me get straight to the point. Give up Fenrir Mercenaries."
L24_1.m_Talk_ENG = L25_1
L25_1 = "先說結論吧，放棄芬里爾傭兵隊吧。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ข้าจะพูดตรงๆ นะ เลิกคิดเรื่องทหารรับจ้างเฟนเรียร์นั่นเสียที"
L24_1.m_Talk_THA = L25_1
L25_1 = "Ta nói thẳng. Từ bỏ chuyện Lính Đánh Thuê Fenrir đi."
L24_1.m_Talk_VTN = L25_1
L25_1 = "先说结论吧，放弃芬里尔佣兵队吧。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Lass mich gleich auf den Punkt kommen. Vergiss die Fenrir-Söldner."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Je ne vais pas y aller par quatre chemins : Renonce aux mercenaires Fenrir."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP10_ACT1_INTERLUDE2@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 422
L25_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "UNIT_SURPRISE"
L25_1.m_Face = L26_1
L25_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L25_1.m_Pos = "C"
L26_1 = "m_Crash"
L25_1[L26_1] = 15
L26_1 = "네? 어째서죠?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "はい？　どうしてですか？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "What? How so?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "什麼？為什麼？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "หา? ทำไมแบบนั้นละครับ?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Cái gì? Sao lại thế?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "什么？为什么？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "... Was? Aber warum?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Pardon ? Pourquoi donc ?"
L25_1.m_Talk_FRA = L26_1
