L29_1 = "EP10_ACT1_INTERLUDE2@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 422
L28_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_DESPAIR"
L29_1 = "CHARLOTTE_ORDER_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "L"
L29_1 = "우리 측 병사들이 거점에 찾아갔을 때는 전부 떠나 버린 뒤였어."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "我々の兵士たちが拠点にたどり着いたときには、すでに全員いなくなっていた。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "By the time our soldiers reached their base, they were already gone."
L28_1.m_Talk_ENG = L29_1
L29_1 = "我方士兵找到據點的時候，她們已經全部離開了。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ตอนที่ทหารของเราไปถึงฐานพวกมัน ที่นั่นก็ไม่มีใครอยู่แล้ว"
L28_1.m_Talk_THA = L29_1
L29_1 = "Khi binh lính của chúng ta đến căn cứ của họ, họ đã biến mất."
L28_1.m_Talk_VTN = L29_1
L29_1 = "我方士兵找到据点的时候，她们已经全部离开了。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Als unsere Soldaten ihre Basis erreichten, waren sie bereits verschwunden."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Quand nos soldats sont arrivés à leur base, ils étaient déjà partis."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP10_ACT1_INTERLUDE2@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 422
L29_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "CHARLOTTE_ORDER_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "L"
L30_1 = "……우두머리였던 <color=#ffd34c>늑대</color>가 죽었으니까."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "……親玉だった<color=#ffd34c>狼</color>が死んでしまったからな。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "...Because their leader, the <color=#ffd34c>Wolf</color>, had passed."
L29_1.m_Talk_ENG = L30_1
L30_1 = "……因為曾經是首領的<color=#ffd34c>狼</color>死了。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "...เพราะ ผู้นำของพวกเขา<color=#ffd34c>หมาป่า</color>ได้จากไปแล้ว"
L29_1.m_Talk_THA = L30_1
L30_1 = "...Bởi vì <color=#ffd34c>Con Sói</color> đã đi qua."
L29_1.m_Talk_VTN = L30_1
L30_1 = "……因为曾经是首领的<color=#ffd34c>狼</color>死了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "... Weil ihr Anführer, der <color=#ffd34c>Wolf</color>, verstorben war."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Puisque leur chef, la <color=#ffd34c>louve</color>... est morte."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP10_ACT1_INTERLUDE2@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 422
L30_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "PRINCE_KNIGHT_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "R"
L31_1 = "단원들의 행적을 점령지까지 샅샅이 찾아 봤다만, 그 날의 전투 이후로 단원들의 행방이 묘연해졌다더군."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "団員たちの痕跡を占領地に至るまで隈なく探したということだが、あの日の戦闘以来、消息がつかめないらしい。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "We went through every single territory they conquered, but none of the members were to be found after the day of the battle."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我們仔細追查了團員們的行蹤，直到佔領區。似乎是在那天的戰鬥之後，團員們就全都失去了蹤跡。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เราไปกันทั่วทุกดินแดนที่ได้พิชิตไป แต่หลังจากวันทำศึกนั่นแล้ว ก็ไม่เจอสมาชิกของพวกมันที่ไหนเลย"
L30_1.m_Talk_THA = L31_1
L31_1 = "Chúng ta đã đi qua mọi lãnh thổ mà họ chinh phục, nhưng chẳng tìm thấy thành viên nào sau ngày xảy ra trận chiến."
L30_1.m_Talk_VTN = L31_1
L31_1 = "我们仔细追查了团员们的行踪，直到占领区。似乎是在那天的战斗之后，团员们就全都失去了踪迹。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wir durchkämmten jedes einzelne besetzte Gebiet, das sie erobert hatten, aber wir konnten sie dennoch nicht ausfindig machen. Seit der Schlacht sind alle Mitglieder spurlos verschwunden."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Nous avons passé au peigne fin chacun des territoires qu'ils ont conquis depuis l'affrontement, mais il n'y a plus personne."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 422
L31_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L31_1.m_bWaitClick = false
L31_1.m_fWaitTime = 0
