L32_1 = {}
L33_1 = "EP10_ACT1_INTERLUDE2@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 422
L32_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_DESPAIR"
L32_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "결전을 앞두고 아쉬운 소식이군요. 함께 싸웠다면 큰 힘이 되었을 텐데요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "決戦を前にして残念な知らせですね。一緒に戦えれば大きな戦力になっていたでしょうに。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "This is grave news. It would have been of great help if they were able to fight alongside us."
L32_1.m_Talk_ENG = L33_1
L33_1 = "決戰在即，這個消息可真讓人遺憾啊。如果她們也能一起作戰，應該會成為一大助力。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ข่าวร้ายมหันต์เลยนะครับนี่ ถ้าพวกเขาอยู่ช่วยเราสู้ได้ก็จะเป็นการดีมาก"
L32_1.m_Talk_THA = L33_1
L33_1 = "Đây là tin tức nghiêm trọng. Giá như họ còn có thể sát cánh chiến đấu với chúng ta."
L32_1.m_Talk_VTN = L33_1
L33_1 = "决战在即，这个消息可真让人遗憾啊。如果她们也能一起作战，应该会成为一大助力。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Das sind enttäuschende Neuigkeiten so kurz vor der entscheidenden Schlacht. Es wäre eine große Hilfe gewesen, wenn sie an unserer Seite gekämpft hätten."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ce sont de mauvaises nouvelles. Avec eux à nos côtés, nos chances de victoires auraient été décuplées."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP10_ACT1_INTERLUDE2@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 422
L33_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "UNIT_SERIOUS"
L33_1.m_Face = L34_1
L34_1 = "PRINCE_KNIGHT_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "그런 인재들이 황실의 명에 따르지 않고 멋대로 굴었으니 문제라는 거다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "そのような粒ぞろいの集団が皇室の命令を無視して、自分勝手に振る舞ったことが問題なのだ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "The problem is that the talents like them were acting on their own, disobeying the royal orders."
L33_1.m_Talk_ENG = L34_1
L34_1 = "那樣的人才不服從皇室的命令，任意妄為，這才是問題。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ปัญหาคือผู้มีพรสวรรค์เช่นพวกมันเคลื่อนไหวเองตามอำเภอใจ ไม่ฟังคำสั่งของราชวงศ์"
L33_1.m_Talk_THA = L34_1
L34_1 = "Vấn đề là họ đã hành động theo ý mình, bất tuân mệnh lệnh hoàng gia."
L33_1.m_Talk_VTN = L34_1
L34_1 = "那样的人才不服从皇室的命令、任意妄为，这才是问题。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Das Problem besteht darin, dass solch talentierte Kämpfer den Befehlen der königlichen Familie nicht Folge leisten und stattdessen auf eigene Faust handeln."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Ils n'en faisaient qu'à leur tête, de toute façon. Au mépris de mes ordres."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP10_ACT1_INTERLUDE2@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 422
L34_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "PRINCE_KNIGHT_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "애석하지만 제국에는 더 이상 전쟁을 지속할 여력이 없어."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "残念だが、帝国はもはや戦争を続ける余力がない。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Grave as it is, the Empire is no longer capable of continuing war."
L34_1.m_Talk_ENG = L35_1
L35_1 = "可惜的是帝國已經沒有繼續戰爭的餘力了。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ก็เลวร้ายมหันต์ดังที่เห็น อาณาจักรไร้สามารถจะทำสงครามต่อแล้ว"
L34_1.m_Talk_THA = L35_1
L35_1 = "Vì sự nghiêm trọng của vấn đề này mà Đế Chế không còn khả năng tiếp tục chiến tranh."
L34_1.m_Talk_VTN = L35_1
L35_1 = "可惜的是帝国已经没有继续战争的余力了。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Wie beunruhigend es auch ist, das Imperium ist nicht länger in der Lage, den Krieg fortzusetzen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Qu'on le veuille ou non, l'Empire n'est plus en mesure de continuer le combat."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP10_ACT1_INTERLUDE2@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 422
L35_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "PRINCE_KNIGHT_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "그들이 있든 없든, 여기서 마왕을 패퇴시켜야 한다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "彼らがいようがいまいが、ここで魔王とは決着をつけねばならない。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Whether they come with us or not, we need to take down the Demon Lord here."
L35_1.m_Talk_ENG = L36_1
L36_1 = "不管有沒有她們，我們都必須在這裡打敗魔王。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ไม่ว่าพวกมันจะมากับเราหรือไม่ จะอย่างไรก็ต้องโค่นเจ้าแห่งดีม่อนเสียที่นี่"
L35_1.m_Talk_THA = L36_1
L36_1 = "Cho dù họ có sát cánh bên chúng ta hay không, chúng ta vẫn cần phải hạ gục Chúa Quỷ tại đây."
L35_1.m_Talk_VTN = L36_1
L36_1 = "不管有没有她们，我们都必须在这里打败魔王。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ob sie an unserer Seite kämpfen oder nicht, wir müssen den Dämonenfürsten hier besiegen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Nous devons y mettre un terme maintenant, avec ou sans leur aide."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP10_ACT1_INTERLUDE2@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 422
L36_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "PRINCE_KNIGHT_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "이 골짜기를 통과하면 수도까지는 거칠 것이 없을 테니까."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "この谷を抜け出れば、首都までは直通だ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "After this creek, there won't be any obstacles until we reach the capital."
L36_1.m_Talk_ENG = L37_1
L37_1 = "越過這個山谷後，在到達首都之前應該都不會有麻煩了。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ข้ามลำธารนี้ไป ก็จะไม่มีอุปสรรคอันใดมาขวางจนกว่าเราจะถึงเมืองหลวงแล้ว"
L36_1.m_Talk_THA = L37_1
L37_1 = "Sau con lạch này, sẽ không còn chướng ngại vật nào nữa cho đến khi chúng ta đến được thủ đô."
L36_1.m_Talk_VTN = L37_1
L37_1 = "通过这个山谷后，在到达首都之前应该都不会有麻烦了。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wenn wir dieses Tal durchqueren, wird es keine Hindernisse mehr geben, bis wir die Hauptstadt erreichen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Une fois passé cette rivière, nous seront bientôt à la capitale."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP10_ACT1_INTERLUDE2@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 422
L37_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_DESPAIR"
L37_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L37_1.m_Pos = "C"
L38_1 = "역시……. 그 때 혼자서 싸우러 가게 내버려 두면 안 됐는데……"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "やっぱり……あの時一人で戦いに行かせるんじゃなかった……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I knew it... I shouldn't have left her to fight alone..."
L37_1.m_Talk_ENG = L38_1
L38_1 = "果然……當時就不該讓她一個人去戰鬥……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ผมทราบดีครับ... แต่เราไม่ควรปล่อยให้เธอต้องสู้ตามลำพังนะครับ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi biết mà... Lẽ ra tôi không nên để cô ấy chiến đấu một mình..."
L37_1.m_Talk_VTN = L38_1
L38_1 = "果然……当时就不该让她一个人去战斗……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ich wusste es ... Ich hätte sie nicht alleine kämpfen lassen sollen ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "J'en étais sûr... nous n'aurions jamais dû les laisser combattre seuls..."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP10_ACT1_INTERLUDE2@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 422
L38_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_IDLE"
L39_1 = "PRINCE_KNIGHT_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "쓸데없는 자책 하지 마라. 그건 늑대의 결정이었다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "今更無駄な自責はやめろ。あれは狼自身が決めたことだ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "It’s useless to blame yourself. It was the Wolf's decision to make."
L38_1.m_Talk_ENG = L39_1
L39_1 = "別做無謂的自責了，那是狼的決定。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "โทษตัวเองไปก็ไม่ได้ประโยชน์อันใด มันเป็นการตัดสินใจของหมาป่าเอง"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tự trách mình cũng chẳng ích gì. Đó là quyết định của Sói."
L38_1.m_Talk_VTN = L39_1
L39_1 = "别做无谓的自责了，那是狼的决定。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Es ist sinnlos, sich selbst die Schuld zu geben. Es war die Entscheidung des Wolfes."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Inutile d'avoir des remords. Cette décision, c'est la louve qui l'a prise."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP10_ACT1_INTERLUDE2@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 422
L39_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "PRINCE_KNIGHT_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "눈앞의 싸움에나 집중하도록. 내키지 않으면 황명이라도 내려 주지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "目の前の戦いに集中しろ。それが難しいようなら勅令を出す。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Focus on what's in front of you. I shall give a royal order if you don't feel like doing so."
L39_1.m_Talk_ENG = L40_1
L40_1 = "專注眼前的戰鬥。如果你不願意，我就要命令你了。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "สนใจแต่เรื่องตรงหน้าเจ้าดีกว่า แต่ถ้าไม่อยากทำ ข้าจะออกคำสั่งราชวงศ์ให้เจ้าทำเอง"
L39_1.m_Talk_THA = L40_1
L40_1 = "Cứ tập trung vào những gì ở phía trước đi. Ta sẽ ra lệnh nếu cậu không thích làm như vậy."
L39_1.m_Talk_VTN = L40_1
L40_1 = "专注眼前的战斗。如果你不愿意，我就要命令你了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Konzentriere dich lieber auf das, was vor dir liegt. Ich werde dir einen königlichen Befehl erteilen, wenn du keine Lust darauf hast."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Concentre-toi plutôt sur la suite. Et si ça ne te plaît pas, dis-toi que c'est un ordre de toute façon."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
