L42_1.m_Face = "UNIT_DESPAIR"
L43_1 = "CHARLOTTE_ORDER_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "L"
L43_1 = "그렇지만 전하, 늑대는 저와 구원자에게 스승이나……"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ですが殿下、狼は私や救世主にとっては師匠ともいうべき……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "But Your Highness, the Wolf was like a master to me as well as the Savi–"
L42_1.m_Talk_ENG = L43_1
L43_1 = "但是，殿下，狼對我和救贖者來說是師父般的……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "แต่ฝ่าบาทคะ หมาป่าเป็นเหมือนอาจารย์ของข้าเช่นกันพระผู้ไถ่แล้วก็– "
L42_1.m_Talk_THA = L43_1
L43_1 = "Nhưng thưa Điện Hạ, Con Sói giống như sư phụ của Đấng Cứu Thế và-"
L42_1.m_Talk_VTN = L43_1
L43_1 = "但是，殿下，狼对我和救赎者来说是老师般的……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Aber Eure Hoheit, der Wolf war für mich wie ein Meister, ebenso für den Erlöser –"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Mais Votre Altesse, la louve était un véritable maître à nos yeux, au Sauveur et à moi..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
