L47_1 = "EP10_ACT1_INTERLUDE2@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 422
L46_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "UNIT_SERIOUS"
L46_1.m_Face = L47_1
L46_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L46_1.m_Pos = "R"
L47_1 = "이번에는 저도 전하처럼 선봉에서 누구보다 열심히 싸우겠어요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "今回は、僕も殿下のように先鋒に立って誰よりも戦いに注力します。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I will fight with everything I have in the front lines, just like you did."
L46_1.m_Talk_ENG = L47_1
L47_1 = "這次我也要像殿下一樣，做個比任何人都更努力戰鬥的先鋒。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เมื่ออยู่แนวหน้า มีอะไรผมจะเอาออกมาใช้สู้ให้หมด เหมือนที่ท่านทำครับ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tôi sẽ chiến đấu hết mình ở tiền tuyến, giống như ngài vậy."
L46_1.m_Talk_VTN = L47_1
L47_1 = "这次我也要像殿下一样，做个比任何人都更努力战斗的先锋。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich werde mit allem, was ich habe, an der Front kämpfen, genau wie Ihr es getan habt, Eure Hoheit."
L46_1.m_Talk_DEU = L47_1
L47_1 = "J'irai me battre au front, comme vous l'avez fait. Et je donnerai tout ce que j'ai."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP10_ACT1_INTERLUDE2@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 422
L47_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L47_1.m_Pos = "R"
L48_1 = "아무도 죽지 않게 할 겁니다. 늑대가 그랬던 것처럼요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "誰も死なせやしません。狼のようには。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I won't let any man die. Just like the Wolf did."
L47_1.m_Talk_ENG = L48_1
L48_1 = "我不會讓任何人死的，就像狼過去做的那樣。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ผมจะไม่ปล่อยให้มีใครตายทั้งนั้น เหมือนที่หมาป่าทำ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi sẽ không để bất kỳ người nào chết. Giống như Con Sói vậy."
L47_1.m_Talk_VTN = L48_1
L48_1 = "我不会让任何人死的，就像狼过去做的那样。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich werde niemanden sterben lassen. Genau wie der Wolf."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je ne laisserai plus personne mourir. Comme elle l'a fait."
