L50_1 = "EP10_ACT1_INTERLUDE2@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 422
L49_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_Face = "UNIT_LAUGH"
L50_1 = "PRINCE_KNIGHT_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "m_Crash"
L49_1[L50_1] = 20
L50_1 = "하하하! 당돌한 소리를 지껄이는군!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ハハハッ！　大胆なことを言う！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Ha ha ha! Such arrogance, I would say."
L49_1.m_Talk_ENG = L50_1
L50_1 = "哈哈哈！很莽撞的發言啊！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฮ่า ฮ่า ฮ่า! ต้องขอบอกว่ายโสนักนะเจ้า"
L49_1.m_Talk_THA = L50_1
L50_1 = "Ha ha ha! Phải nói là cậu khá kiêu ngạo đấy."
L49_1.m_Talk_VTN = L50_1
L50_1 = "哈哈哈！很莽撞的发言啊！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Hahaha! Wie tollkühn du doch bist!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Ha ha ha ! Ce n'est pas l'arrogance qui t'étouffe, en tout cas."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP10_ACT1_INTERLUDE2@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 422
L50_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "UNIT_PRIDE"
L50_1.m_Face = L51_1
L51_1 = "PRINCE_KNIGHT_NULL_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "하지만 썩 나쁘지 않아. 그 정도 배짱은 있어야 제국의 총기사단장직에 걸맞지."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "しかしその気概は悪くはない。それでこそ帝国の総騎士団長というものだ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "But not bad at all. That's what I require from the Supreme Commander of the Empire's knights."
L50_1.m_Talk_ENG = L51_1
L51_1 = "還不錯。有這樣的膽量，才配得上帝國總騎士團長一職。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "แต่ก็ไม่เลวเสียเดียวหรอก เพราะที่ข้าต้องการจากผู้บัญชาการสูงสุดของภาคีที่ฝีมือเยี่ยมที่สุดของอัศวินอาณาจักร ก็คือเช่นนั้น "
L50_1.m_Talk_THA = L51_1
L51_1 = "Nhưng không tệ chút nào. Đây mới là thứ ta cần ở Tổng tư lệnh của quân đoàn mạnh nhất đế chế."
L50_1.m_Talk_VTN = L51_1
L51_1 = "还不错。有这样的胆量，才配得上帝国总骑士团长一职。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Aber nicht schlecht. Man muss genau diesen Mut haben, um der Position des Oberbefehlshabers der Ritter des Imperiums würdig zu sein."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Ceci dit, j'admire ta détermination. Je n'en attends pas moins du Commandant suprême des chevaliers de l'empire."
L50_1.m_Talk_FRA = L51_1
