L4_1 = "UNIT_SURPRISE"
L3_1.m_Face = L4_1
L3_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L3_1.m_Pos = "L"
L4_1 = "총기사단장이요?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "総騎士団長ですって？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "The Commander?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "總騎士團長？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ผู้บัญชาการเหรอครับ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Tổng Tư Lệnh?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "总骑士团长？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Der Oberbefehlshaber?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Le commandant suprême ?"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP10_ACT1_INTERLUDE2@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 422
L4_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L4_1.m_Pos = "R"
L5_1 = "칙명으로만 임명되는 특별한 직위다. 제국 역사를 통틀어 세 명뿐이었어."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "勅命によってのみ与えることができる特別な職位だ。帝国史上これまで三人しかいない。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "It's a special status given by royal decree only. Three people have been granted the title throughout the history of this Empire."
L4_1.m_Talk_ENG = L5_1
L5_1 = "這是僅通過敕命任命的特別職位。整個帝國歷史上也只有三位。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เป็นสถานะพิเศษที่มอบให้ได้ก็ด้วยมีราชโองการเท่านั้นน่ะ ตลอดประวัติศาสตร์ของอาณาจักร เคยมีแค่สามคนที่ได้สถานะนี้"
L4_1.m_Talk_THA = L5_1
L5_1 = "Đó là danh hiệu đặc biệt chỉ có sắc lệnh hoàng gia mới có quyền ban tặng. Trong suốt chiều dài lịch sử của đế chế này, có ba người đã được ban danh hiệu đó."
L4_1.m_Talk_VTN = L5_1
L5_1 = "这是仅通过敕命任命的特别职位。整个帝国历史上也只有三位。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Es handelt sich um einen Sonderstatus, der nur durch königlichen Erlass gewährt wird. Im Laufe der Geschichte dieses Imperiums wurde dieser Titel nur drei Personen verliehen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "C'est un statut spécial conféré uniquement par un décret royal. Seuls trois individus ont été nommés ainsi au cours de notre histoire."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP10_ACT1_INTERLUDE2@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 422
L5_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_LAUGH"
L5_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L5_1.m_Pos = "R"
L6_1 = "하지만 그 자리는 전하께서 노리시던 것 아니었습니까?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "しかし、殿下がそれを目指されていたのでは？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "But isn't that a title you wanted, Your Highness?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "但這不是殿下一直想要的位置嗎？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แต่นั่นเป็นตำแหน่งที่ท่านปรารถนาไม่ใช่เหรอครับ ฝ่าบาท?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nhưng đó không phải là danh hiệu mà ngài muốn sao, Điện Hạ?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "但这不是殿下一直想要的位置么？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Aber war das nicht ein Titel, den Ihr wolltet, Eure Hoheit?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mais ce titre... n'est-ce pas celui que vous convoitiez, Votre Altesse ?"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
