L8_1 = "EP10_ACT1_INTERLUDE2@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 422
L7_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_LAUGH"
L8_1 = "PRINCE_KNIGHT_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L8_1 = "물론 몇 년 전까지는 그랬지."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "ああ、数年前まではな。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "A few years back, yes."
L7_1.m_Talk_ENG = L8_1
L8_1 = "幾年前確實如此。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "สองสามปีก่อนก็ใช่"
L7_1.m_Talk_THA = L8_1
L8_1 = "Một vài năm trước thì là vậy."
L7_1.m_Talk_VTN = L8_1
L8_1 = "几年前确实如此。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ja. Bis vor ein paar Jahren war das noch so."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Il y a quelques années, si."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP10_ACT1_INTERLUDE2@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 422
L8_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "PRINCE_KNIGHT_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L9_1 = "허나 나는 황태자로서 나라를 이끌 몸이 아니던가?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "だが、私は皇太子として国を率いる存在だ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "However, I am the crown prince who is to lead this Empire."
L8_1.m_Talk_ENG = L9_1
L9_1 = "不過身為皇太子，肩負著領導國家之重任。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แต่ยังไงข้าก็เป็นมกุฎราชกุมารผู้นำอาณาจักรอยู่แล้วนี่"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tuy nhiên, ta là thái tử, người sẽ lãnh đạo đế chế này."
L8_1.m_Talk_VTN = L9_1
L9_1 = "不过身为皇太子，肩负着领导国家之重任。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich bin jedoch der Kronprinz, der dieses Imperium führen soll."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Mais je suis le prince héritier. L'homme qui doit diriger cet empire."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP10_ACT1_INTERLUDE2@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 422
L9_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "UNIT_PRIDE"
L9_1.m_Face = L10_1
L10_1 = "PRINCE_KNIGHT_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "전쟁이 끝났다고 구원자를 변방 시골로 돌아가게 내버려 두면 온 세상이 비웃을 거다."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "戦争が終わったからといって、救世主を辺境の田舎の地に帰らせるようでは、世界中から笑われるだろう。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "The whole world will mock me if I send off the Savior to a backwater village after the war is over."
L9_1.m_Talk_ENG = L10_1
L10_1 = "如果戰爭結束後，這麼任由救贖者解甲歸田，全王國的人都會嘲笑我的。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เกิดสงครามจบแล้วข้าส่งพระผู้ไถ่ไปอยู่หมู่บ้านหลังเขาขึ้นมา ทั้งโลกคงล้อเลียนข้าจม"
L9_1.m_Talk_THA = L10_1
L10_1 = "Cả thế giới sẽ cười vào mặt ta nếu ta đuổi Đấng Cứu Thế trở lại làng quê hẻo lánh sau khi chiến tranh kết thúc."
L9_1.m_Talk_VTN = L10_1
L10_1 = "如果战争结束后，这么任由救赎者解甲归田，全王国的人都会嘲笑我的。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Die ganze Welt wird mich verspotten, wenn ich den Erlöser nach Kriegsende einfach in irgendein abgelegenes Dorf schicke."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Que pensera le monde si je renvoie le Sauveur dans son village de péquenauds dès le lendemain de la guerre ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "EP10_ACT1_INTERLUDE2@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 422
L10_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "UNIT_SERIOUS"
L10_1.m_Face = L11_1
L11_1 = "HOLY_KNIGHT_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "결국 구원자님을 이용하겠다는 것 아닙니까?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "結局救世主様を利用する、ということですよね？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "So you're just using him?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "說到底不就是想利用救贖者大人嗎？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ท่านก็เพียงใช้งานเขาหรือ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Vậy là ngài chỉ lợi dụng ngài ấy thôi sao?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "说到底不就是想利用救赎者大人吗？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Letztendlich nutzt Ihr den Erlöser also nur für Eure Zwecke aus?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "En fait, vous l'utilisez juste à votre avantage..."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP10_ACT1_INTERLUDE2@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 422
L11_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "HOLY_KNIGHT_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "심보가 고약하시군요, 전하."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "人が悪いですよ、殿下。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "How malevolent of you, Your Highness."
L11_1.m_Talk_ENG = L12_1
L12_1 = "城府很深呢，殿下。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ช่างชั่วช้าอะไรเช่นนี้ฝ่าบาท"
L11_1.m_Talk_THA = L12_1
L12_1 = "Ngài thật ác độc, Điện Hạ."
L11_1.m_Talk_VTN = L12_1
L12_1 = "心是黑的啊，殿下。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Wie heimtückisch von Euch, Eure Hoheit."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Vous êtes décidément bien fourbe, Votre Altesse."
L11_1.m_Talk_FRA = L12_1
