L15_1 = "EP10_ACT1_INTERLUDE2@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 422
L14_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_IDLE"
L15_1 = "CHARLOTTE_ORDER_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "L"
L15_1 = "언동에 주의해 주십시오, 루크레시아. 성녀라고 목이 안 날아가는 건 아닙니다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "言葉を慎まれよ、ルクレシア。聖女といえど、処刑の対象にならないわけではない。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Choose your words wisely, Lucrecia. Your title of \"Saintess\" will not save you from getting sentenced to death."
L14_1.m_Talk_ENG = L15_1
L15_1 = "注意你的言辭，露可蕾西亞。聖女並不代表不會掉腦袋。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ระวังคำพูดคำจาเจ้าเสียบ้างลูเครเซีย ถึงมีสถานะเป็น \"นักบวชหญิง\" ก็ไม่ได้แปลว่าโดนประหารไม่ได้นะ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Dùng từ cho khôn khéo vào, Lucrecia. Danh hiệu \"Thánh nữ\" cũng không cứu cô khỏi tội tử hình đâu."
L14_1.m_Talk_VTN = L15_1
L15_1 = "注意你的言辞，卢克雷西亚。圣女并不代表不会掉脑袋。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Wähle deine Worte mit Bedacht, Lucrecia. Der Titel der „Heiligen“ wird dich nicht davor bewahren, mit dem Kopf unter der Guillotine zu landen."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Surveillez vos propos, Lucrecia. Être la Sainte ne vous met pas pour autant à l'abri de la guillotine."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP10_ACT1_INTERLUDE2@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 422
L15_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "HOLY_KNIGHT_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "R"
L16_1 = "m_Crash"
L15_1[L16_1] = 15
L16_1 = "윽……! 내가 아직도 그런 협박에 겁먹을 것 같아?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "くっ……！　私がまだそんな脅しに怖気づくとでも？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Ugh...! You think your threats still work against me?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "呃……！你覺得我現在還會怕這種威脅嗎？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "อึก...! คิดว่าการขู่ฆ่าข้าจะยังได้ผลอยู่อีกเหรอ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Ugh...! Cô nghĩ mấy lời đe dọa đó còn dùng được với tôi sao?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "呃……！你觉得我现在还会怕这种威胁吗?"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Urgh ...! Glaubst du wirklich, dass du mir mit solchen Drohungen immer noch Angst einflößen könntest?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Ngh... ! Tu penses vraiment que tes menaces fonctionnent encore avec moi ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "EP10_ACT1_INTERLUDE2@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 422
L16_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "UNIT_PRIDE"
L16_1.m_Face = L17_1
L17_1 = "CHARLOTTE_ORDER_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "L"
L17_1 = "협박으로 끝날 것 같습니까?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "脅しで済むと思われるか？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Do you think this is a mere threat?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "你認為這僅僅是威脅嗎？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เจ้าคิดว่านี่แค่คำขู่หรือ?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Cô nghĩ đây chỉ là đe dọa thôi sao?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "你认为这仅仅是威胁吗?"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Glaubst du, dass es nur eine leere Bedrohung ist?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Qui a dit qu'il s'agissait simplement d'une menace ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "EP10_ACT1_INTERLUDE2@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 422
L17_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "HOLY_KNIGHT_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "R"
L18_1 = "m_Crash"
L17_1[L18_1] = 10
L18_1 = "이…… 이래서 귀족들이란!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "こ……これだから貴族は！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I... I hate aristocrats!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "所……所以我才痛恨你們這些貴族！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ข้า... ข้าชิงชังพวกเจ้าขุนมูลนายนัก!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Tôi... tôi ghét quý tộc!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "所……所以我才恨你们这些贵族！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich ... hasse diese Adligen!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Ngh... au diable la noblesse !"
L17_1.m_Talk_FRA = L18_1
