L20_1 = "EP10_ACT1_INTERLUDE2@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 422
L19_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_LAUGH"
L20_1 = "PRINCE_KNIGHT_NULL_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "하하, 그대에게 정치에 신경을 쓸 겨를이 있었나?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "ハハ、貴様に政治を気にする余力などあったのか？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Ha ha, I know you don't have time to think about politics."
L19_1.m_Talk_ENG = L20_1
L20_1 = "哈哈，你還有時間關注政治？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ฮ่าฮ่า ข้ารู้หรอกว่าเจ้าไม่มีเวลามาคิดเรื่องการเมือง"
L19_1.m_Talk_THA = L20_1
L20_1 = "Ha ha, ta biết cô không có thời gian suy nghĩ về vấn đề chính trị."
L19_1.m_Talk_VTN = L20_1
L20_1 = "哼，你还有时间关注政治？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Haha, ich weiß, dass du keine Zeit hast, dir den Kopf über Politik zu zerbrechen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Ha ha. As-tu vraiment le temps de penser à la politique ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP10_ACT1_INTERLUDE2@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 422
L20_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "PRINCE_KNIGHT_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "알고 있겠다만, 성녀의 혼인은 교리로 금지하고 있다."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "知っていると思うが、聖女の婚姻は教義によって禁じられている。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "As you know, marriage is forbidden for Saints."
L20_1.m_Talk_ENG = L21_1
L21_1 = "你應該知道吧，教義是禁止聖女結婚的。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "แต่เจ้าก็รู้อยู่แล้ว ว่านักบุญแต่งงานไม่ได้"
L20_1.m_Talk_THA = L21_1
L21_1 = "Như cô đã biết, các đời Thánh Nữ bị cấm kết hôn."
L20_1.m_Talk_VTN = L21_1
L21_1 = "你应该知道吧，教义是禁止圣女结婚的。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wie du weißt, ist der Heiligen die Ehe nicht gestattet."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Dois-je te rappeler que le mariage est formellement refusé à la Sainte ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP10_ACT1_INTERLUDE2@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 422
L21_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "UNIT_SURPRISE"
L21_1.m_Face = L22_1
L22_1 = "HOLY_KNIGHT_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "m_Crash"
L21_1[L22_1] = 20
L22_1 = "그, 그건 갑자기 무슨 말씀입니까?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "そ、それはいきなりどういう意味でしょうか？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I-I don't know what you're talking about."
L21_1.m_Talk_ENG = L22_1
L22_1 = "你，你突然說這個做什麼？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ทะ-ท่านพูดอะไรไม่เห็นรู้เรื่อง"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tôi không biết ngài đang lảm nhảm về cái gì."
L21_1.m_Talk_VTN = L22_1
L22_1 = "你、你突然说这个做什么？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "I-ich weiß nicht, wovon Ihr so plötzlich sprecht."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Q-Que voulez-vous dire ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP10_ACT1_INTERLUDE2@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 422
L22_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "UNIT_PRIDE"
L22_1.m_Face = L23_1
L23_1 = "PRINCE_KNIGHT_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "그깟 무의미한 신경전보다 더 중요한 데 집중하란 뜻이다."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "そのような無意味な心理戦を繰り広げるよりも、重要なことに集中しろということだ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "What I am telling you is to focus on what's important, instead of getting involved in irrelevant feuds."
L22_1.m_Talk_ENG = L23_1
L23_1 = "我的意思是，比起那種毫無意義的心理戰，你應該專注於更重要的事。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ที่ข้าจะบอกก็คือ จงจดจ่อกับเรื่องสำคัญเสียเถอะ อย่าไปมัวพันพัวกับความอาฆาตแค้นที่ไม่เกี่ยวข้องเลย"
L22_1.m_Talk_THA = L23_1
L23_1 = "Điều ta đang nói là cô hãy tập trung vào chuyện quan trọng, thay vì dính vào những thù hận không đâu."
L22_1.m_Talk_VTN = L23_1
L23_1 = "我的意思是，比起那种毫无意义的心理战，你应该专注于更重要的事。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Das bedeutet, dass du dich auf wichtigere Dinge als  solche sinnlosen Psychospielchen konzentrieren sollst."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Concentre-toi sur ton rôle, au lieu de perdre du temps avec ces futilités."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP10_ACT1_INTERLUDE2@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 422
L23_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "PRINCE_KNIGHT_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "그대의 알량한 소원을 성취하고 싶다면 말이다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "貴様のそのちっぽけな夢を叶えたかったらな。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "If you want your pathetic little wish to come true, that is."
L23_1.m_Talk_ENG = L24_1
L24_1 = "要想實現你那不怎麼樣的願望的話。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ถ้าอยากให้ปรารถนาน่าสมเพชนั่นเป็นจริงขึ้นมา ก็ดังคำข้าแหละ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Nếu cô còn muốn điều ước nhỏ bé thảm hại của mình thành sự thật."
L23_1.m_Talk_VTN = L24_1
L24_1 = "要想实现你那不怎么样的愿望的话。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Wenn du möchtest, dass dein erbärmlicher kleiner Wunsch in Erfüllung geht."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Si tu veux que ton minable petit vœu s'exauce un jour..."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
