L28_1 = "루크레시아, 결혼할 사람이 있었어?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ルクレシア、結婚する相手がいたの？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Oh, I didn't know you have a fiance, Lucrecia."
L27_1.m_Talk_ENG = L28_1
L28_1 = "露可蕾西亞，你有要結婚的人嗎？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ไม่ยักรู้ว่าคุณอยากแต่งงานด้วย ลูเครเซีย"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tôi không biết là cô muốn kết hôn đấy, Lucrecia."
L27_1.m_Talk_VTN = L28_1
L28_1 = "卢克雷西亚，你有要结婚的人吗？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Oh, ich wusste ja gar nicht, dass du einen Verlobten hast, Lucrecia."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Je ne savais pas que tu étais fiancée, Lucrecia !"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP10_ACT1_INTERLUDE2@178#Talk"
