L29_1 = "UNIT_SURPRISE"
L28_1.m_Face = L29_1
L29_1 = "HOLY_KNIGHT_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "R"
L29_1 = "m_Crash"
L28_1[L29_1] = 20
L29_1 = "아닙니다! 절대로 아니에요!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "いいえ！　決してそのようなことはありません！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "No! Not at all!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "沒有！絕對沒有！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เปล่าค่ะ! ไม่ใช่สักนิด!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Không! Không hề!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "没有！绝对没有！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Nein! Das habe ich auch nicht!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Non ! C'est un malentendu !"
L28_1.m_Talk_FRA = L29_1
