L31_1 = "EP10_ACT1_INTERLUDE2@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 422
L30_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L30_1.m_Pos = "L"
L31_1 = "다행이다. 루크레시아는 이제 모두에게 사랑 받는 성녀잖아."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "よかった。ルクレシアはもうみんなの聖女だからね。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "That's a relief. You are the Saintess that everyone loves."
L30_1.m_Talk_ENG = L31_1
L31_1 = "那就好。露可蕾西亞如今可是深受所有人愛戴的聖女。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "โล่งใจไปที คุณเป็นนักบุญหญิงที่ใครๆ ก็รักนะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Thật nhẹ nhõm. Cô là Thánh Nữ mà mọi người đều yêu mến."
L30_1.m_Talk_VTN = L31_1
L31_1 = "那就好。卢克雷西亚如今可是深受所有人爱戴的圣女。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Was für eine Erleichterung. Du bist schließlich die Heilige, die von allen so sehr geliebt wird."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Quel soulagement. Maintenant que tu es la Sainte, le peuple entier te donne son amour."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP10_ACT1_INTERLUDE2@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 422
L31_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L31_1.m_Pos = "L"
L32_1 = "성녀직에서 내려온다고 하면 다들 아쉬워할 거야."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "聖女をやめたら、みんな悲しがると思うよ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "People would be sad if they see you stepping down from the title."
L31_1.m_Talk_ENG = L32_1
L32_1 = "如果你說要辭去聖女一職，大家都會覺得可惜的。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เกิดคุณลงจากตำแหน่งขึ้นมา คนคงเสียใจกันแย่"
L31_1.m_Talk_THA = L32_1
L32_1 = "Mọi người sẽ rất buồn nếu cô từ bỏ danh hiệu."
L31_1.m_Talk_VTN = L32_1
L32_1 = "如果你说要辞去圣女一职，大家都会觉得可惜的。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Die Menschen wären alle so enttäuscht, wenn du den Titel der Heiligen ablegen würdest."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Si tu renonçais à ton titre, je suis sûr que tout le monde serait déçu."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP10_ACT1_INTERLUDE2@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 422
L32_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_DESPAIR"
L33_1 = "HOLY_KNIGHT_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "R"
L33_1 = "아뇨, 구원자님. 제 말은……."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "いいえ、救世主様。私は……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "No, Savior, that's not what I meant..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "不是，救贖者大人。我的意思是……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "มิได้ค่ะพระผู้ไถ่ ข้าไม่ได้หมายความเช่นนั้น..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Không, Đấng Cứu Thế, ý tôi không phải thế..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "没有，救赎者大人。我的意思是……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Nein, Erlöser. So habe ich das nicht gemeint ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Non, Sauveur. Je veux dire..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
