L35_1 = "EP10_ACT1_INTERLUDE2@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 422
L34_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_IDLE"
L35_1 = "PRINCE_KNIGHT_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "얘기가 많이 돌아왔지만, 결국 생존자들의 처우는 그들 자신이 정해야겠지."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "話がだいぶ逸れてしまったが、結局生き延びた者は自らの境遇を決めねばならない。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "This conversation deviated to an excessive extent, but my conclusion is that the survivors will need to look after themselves."
L34_1.m_Talk_ENG = L35_1
L35_1 = "雖然說了很多，但倖存者應該如何處理，最終還是該由他們自己決定。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "การสนทนานี้ออกนอกลู่นอกทางเกินงามไปแล้ว แต่ข้อสรุปของข้าก็คือ ผู้รอดชีวิตต้องดูแลตัวเอง"
L34_1.m_Talk_THA = L35_1
L35_1 = "Câu chuyện phiếm này đã đi hơi xa rồi, nhưng tóm lại, những người sống sót sẽ cần phải tự chăm sóc bản thân đấy."
L34_1.m_Talk_VTN = L35_1
L35_1 = "虽然说了很多，但幸存者应该如何处理，最终还是该由他们自己决定。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Dieses Gespräch ist sehr weit abgeschweift, aber ich komme zu dem Schluss, dass die Überlebenden für sich selbst sorgen müssen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Cette conversation est en train de s'écarter de son propos initial. Quoi qu'il en soit, vous devez vous décider."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP10_ACT1_INTERLUDE2@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 422
L35_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "UNIT_SERIOUS"
L35_1.m_Face = L36_1
L36_1 = "PRINCE_KNIGHT_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "그대들은 어찌 하고 싶나?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "そなたらはどうしたいのだ？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "What is it that you wish?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "你們想怎麼樣？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "พวกเจ้าประสงค์สิ่งใดกันเล่า?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đó có phải là điều cô muốn không?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "你们想怎么样？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Was hast du jetzt vor?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Que désirez-vous, exactement ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP10_ACT1_INTERLUDE2@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 422
L36_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "PRINCE_KNIGHT_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "마왕 네헤모트에게 복수하길 원하나? 아니면 여생만큼은 평화롭게 보내길 바라나?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "魔王ネヘモトへの復讐か？　それとも残りの人生は平和に過ごしたいか？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Do you wish to take vengeance on Nehemoth, the Demon Lord? Or do you wish to live your remaining life in peace?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "想報復魔王貝赫莫特嗎？還是說希望平安地度過餘生？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "อยากล้างแค้นเจ้าแห่งดีม่อนนีฮีมอท? หรืออยากใช้ชีวิตที่เหลืออย่างสงบสุข?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Cô có muốn báo thù Chúa Quỷ Nehemoth không? Hay cô có muốn sống phần đời còn lại trong hòa bình không?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "想要向魔王涅赫摩斯复仇吗？还是说希望平安地度过余生？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Möchtest du dich an Nehemoth, dem Dämonenfürsten, rächen? Oder möchtest du den Rest deines Lebens in Frieden verbringen?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Souhaitez-vous prendre votre vengeance sur Nehemoth, le Seigneur démon ? Ou poursuivre le peu qu'il vous reste à vivre en paix ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP10_ACT1_INTERLUDE2@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 422
L37_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "UNIT_PRIDE"
L37_1.m_Face = L38_1
L38_1 = "PRINCE_KNIGHT_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "자, 선택해라. 원한다면 센트럴 팰리스로 갈 수 있도록 병력을 붙여 주마."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "さぁ、選べ。望めばセントラルパレスへ行けるよう、兵士をつけてやる。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Choose. If you want, I will provide you with troops to head towards the Central Palace."
L37_1.m_Talk_ENG = L38_1
L38_1 = "好了，做選擇吧。如果你們需要，我會派兵力送你們去聖特羅貝里斯。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เลือกเสีย หากต้องการ ข้าจะให้กองกำลังมุ่งหน้าไปวังกลางกับพวกเจ้า"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chọn đi. Nếu cô muốn, ta sẽ cho cô quân đội để tới Cung Điện Trung Tâm."
L37_1.m_Talk_VTN = L38_1
L38_1 = "好了，做选择吧。如果你们需要，我会派兵力送你们去中央宫。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Entscheide dich. Wenn du möchtest, werde ich dir Truppen zur Verfügung stellen, die dich zum Central Palace begleiten können."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Choisissez. Si c'est la guerre que vous voulez, je mettrai des troupes à votre disposition au Palais Central."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
