L40_1 = "EP10_ACT1_INTERLUDE2@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 422
L39_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_IDLE"
L40_1 = "YOOMINA_FENRIR_NEXT_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "대답은 여기 올 때부터 정해져 있었어."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "答えはここに来た時点で決まってた。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "The answer was set the minute we entered here."
L39_1.m_Talk_ENG = L40_1
L40_1 = "從我們來這裡的那一刻起，答案就已經註定了。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "คำตอบชัดเจนตั้งแต่เราเข้ามาที่นี่แล้วค่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Câu trả lời đã được định sẵn ngay giây phút chúng tôi bước vào đây."
L39_1.m_Talk_VTN = L40_1
L40_1 = "从我们来这里的那一刻起，答案就已经注定了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Die Antwort stand bereits fest, als wir diesen Ort betreten haben."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Notre décision était déjà prise avant même qu'on débarque ici."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
