L41_1 = "YOOMINA_FENRIR_NEXT_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "싸우겠어. 네헤모트와."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "戦うよ。ネヘモトと。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "We're going to fight. Against Nehemoth."
L40_1.m_Talk_ENG = L41_1
L41_1 = "我們要和貝赫莫特戰鬥。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เราจะสู้ กับนีฮีมอท"
L40_1.m_Talk_THA = L41_1
L41_1 = "Chúng ta sẽ chiến đấu. Chống lại Nehemoth."
L40_1.m_Talk_VTN = L41_1
L41_1 = "我们要和涅赫摩斯战斗。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Wir werden kämpfen. Gegen Nehemoth."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Nous allons nous battre. Contre Nehemoth."
L40_1.m_Talk_FRA = L41_1
