L44_1 = "UNIT_SURPRISE"
L43_1.m_Face = L44_1
L43_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L43_1.m_Pos = "L"
L44_1 = "m_Crash"
L43_1[L44_1] = 15
L44_1 = "저, 정말인가요?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ほ、本当ですか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "R-really?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "真，真的嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "จะ-จริงเหรอครับ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "T-thật sao?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "真、真的吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "W-wirklich?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "V-Vraiment ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP10_ACT1_INTERLUDE2@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 422
L44_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L44_1.m_Pos = "R"
L45_1 = "……놀랍군. 정예 병력 중에도 겁에 질린 나머지 마왕의 수하들과 두 번 싸우지 못하는 자들이 부지기수인데."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "……驚きだな。精鋭の兵士でも一度戦えば、恐怖のあまり魔王の手下とは二度と戦えないことが多いのに。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "...Impressive. Most wouldn't dare fight against the Demon Lord and his forces, not even the elite soldiers."
L44_1.m_Talk_ENG = L45_1
L45_1 = "……我很驚訝。即使在精銳兵力中，被嚇得不敢與魔王手下交戰的人也不計其數。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "...น่าประทับใจจริงๆ คนส่วนใหญ่คงไม่กล้าสู้กับเจ้าแห่งดีม่อนแล้วก็กองกำลังของเขาหรอก ต่อให้เป็นทหารชั้นแนวหน้าก็เถอะ"
L44_1.m_Talk_THA = L45_1
L45_1 = "...Ấn tượng đấy. Hầu hết mọi người sẽ không dám chiến đấu chống lại Chúa Quỷ và lực lượng của hắn, kể cả những binh lính tinh nhuệ."
L44_1.m_Talk_VTN = L45_1
L45_1 = "……我很惊讶。即使在精锐兵力中，被吓得不敢与魔王手下交战的人也不计其数。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "... Beeindruckend. Die meisten würden es nicht wagen, gegen den Dämonenfürsten und seine Streitkräfte anzutreten, nicht einmal die Elitesoldaten."
L44_1.m_Talk_DEU = L45_1
L45_1 = "... Impressionnant. Même nos meilleurs soldats d'élite y réfléchiraient à deux fois avant d'aller affronter le Seigneur démon."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
