L47_1 = "EP10_ACT1_INTERLUDE2@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 422
L46_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_LAUGH"
L47_1 = "PRINCE_KNIGHT_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "그래야지. 우리에게서 내일을 앗아간 자가 아니더냐."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "よく言った。奴らは我々の未来を奪ったのだからな。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Of course they would fight. It is the very one who took away our future."
L46_1.m_Talk_ENG = L47_1
L47_1 = "也難怪。那些人可是奪走了我們未來的不是嗎。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ต้องสู้แน่นอนอยู่แล้ว ก็มันเป็นคนชิงเอาอนาคตของเราไป"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tất nhiên họ sẽ chiến đấu. Đó là kẻ đã lấy đi tương lai của chúng ta."
L46_1.m_Talk_VTN = L47_1
L47_1 = "也难怪。那些人可是夺走了我们未来的不是吗。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Natürlich sollten sie kämpfen. Er war schließlich derjenige, der uns unsere Zukunft genommen hat."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Il faut bien qu'ils se battent s'ils veulent avoir un futur."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP10_ACT1_INTERLUDE2@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 422
L47_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "PRINCE_KNIGHT_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "알렌 경, 그레이스가 남긴 무구를 저들에게 하사해도 괜찮겠나?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "アレン、グレースが残した武具をこの者らに与えようと思うがどうだ？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Sir Allen, would you mind if I bestow them the Armament that Grace left behind?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "艾倫卿，我把葛瑞絲留下的武器賜給他們可以嗎？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เซอร์อันเลน จะว่าอะไรหรือไม่หากข้าจะมอบยุทธภัณฑ์ที่เกรซทิ้งไว้ให้พวกมันไป?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ngài Allen, ngài có phiền không nếu ta ban cho họ Vũ khí mà Đức Ngài đã để lại?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "艾伦爵士，我把格蕾丝留下的武器赐给他们可以吗？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Sir Allen, würde es dir etwas ausmachen, wenn ich ihnen die Bewaffnung schenke, die Grace hinterlassen hat?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Sire Allen, je peux leur donner les armes qui appartenaient à Grace ?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
