L50_1.m_Face = "UNIT_LAUGH"
L50_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L50_1.m_Pos = "R"
L51_1 = "예, 전하. 그녀도 그렇게 해 주길 바랄 겁니다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "はい、殿下。きっと彼女もそれを望んでいると思います。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Not at all, Your Highness. Grace would have wanted the same."
L50_1.m_Talk_ENG = L51_1
L51_1 = "是的，殿下。她也會希望您這樣做的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ไม่เลยครับฝ่าบาท เกรซเองก็คงต้องการเช่นนั้น"
L50_1.m_Talk_THA = L51_1
L51_1 = "Không hề, thưa Điện Hạ. Đức Ngài cũng muốn như vậy."
L50_1.m_Talk_VTN = L51_1
L51_1 = "没问题，殿下。想必她也会希望您这么做。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Mitnichten, Eure Hoheit. Grace hätte es so gewollt."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Bien entendu, Votre Altesse. C'est ce qu'elle aurait souhaité, elle aussi."
L50_1.m_Talk_FRA = L51_1
