L3_1 = "UNIT_PRIDE"
L2_1.m_Face = L3_1
L3_1 = "PRINCE_KNIGHT_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "좋다. 내일 아침 출정식이 열릴 예정이니 그대들도 참석하도록."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "決まりだな。明日の朝は出征式だ。そなたらも参席せよ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Good. The celebration of war starts tomorrow morning. You are all required to attend."
L2_1.m_Talk_ENG = L3_1
L3_1 = "好。那麼明天早晨舉行的出征儀式，你們也參加吧。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เช่นนั้นก็ดี งานฉลองสงครามจะเริ่มพรุ่งนี้เช้า พวกเจ้าทุกคนต้องมาร่วมด้วย"
L2_1.m_Talk_THA = L3_1
L3_1 = "Tốt. Lễ ra quân bắt đầu vào sáng mai. Tất cả đều phải tham dự."
L2_1.m_Talk_VTN = L3_1
L3_1 = "好。那么明天早晨举行的远征仪式，你们也参加吧。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Gut. Die Kriegszeremonie beginnt morgen früh. Ihr seid alle zur Teilnahme verpflichtet."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Bien. La cérémonie de départ au combat aura lieu demain matin. Vous êtes priés d'y assister, tous autant que vous êtes."
L2_1.m_Talk_FRA = L3_1
