L5_1 = "UNIT_HATE"
L4_1.m_Face = L5_1
L5_1 = "CUTSCENE_AMBIENT_WIND"
L4_1.m_StartBGMFileName = L5_1
L5_1 = "SEO_YOON_ALT_CA_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "유미나, 갑자기 왜 그런 쓸데없는 말을 꺼내?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "ミナ、いきなりどうしてあんなことを言ったの？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Yoo Mina, why would you say such a thing?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "……米娜，你幹嘛突然說那些廢話啊？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ยู มีนา มันเรื่องอะไรถึงพูดแบบนั้น?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Yoo Mina, sao cô lại nói thế?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "……米娜，你干嘛突然说那些废话啊？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Yoo Mina, warum hast du plötzlich so etwas Dummes gesagt?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mina, non mais qu'est-ce qui t'a pris ?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP10_ACT1_INTERLUDE2@205#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 422
L5_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "SEO_YOON_ALT_CA_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "이건 지금 현실 같은 환각이야. 여기서 다치면 현실에도 영향이 갈 수 있다고."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "今のこれは現実に限りなく近い幻覚よ。ここで怪我をすれば現実にも影響があるかもしれないわ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "The hallucination we're in is very much real. If we get hurt here, it might affect us in reality."
L5_1.m_Talk_ENG = L6_1
L6_1 = "如果這裡是像現實一樣逼真的幻覺。那麼受傷的話，對現實可能也會有影響。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ภาพหลอนที่นี่มันสมจริงสุดๆ ไปเลยนะ เกิดเราบาดเจ็บที่นี่ ก็จะมีผลกับความเป็นจริงไปด้วย"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ảo giác mà chúng ta đang trải qua rất thật. Nếu bị thương, nó cũng có thể ảnh hưởng đến chúng ta ở hiện thực."
L5_1.m_Talk_VTN = L6_1
L6_1 = "如果这里是像现实一样逼真的幻觉。那么受伤的话，对现实可能也会有影响。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Die Halluzination, in der wir uns befinden, ist sehr real. Wenn wir hier verletzt werden, könnte das auch Auswirkungen auf uns in der Realität haben."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Cette illusion est on ne peut plus réelle. S'il nous arrive quelque chose ici, ça risque de nous affecter dans la réalité."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP10_ACT1_INTERLUDE2@206#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 422
L6_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "UNIT_SERIOUS"
L6_1.m_Face = L7_1
L7_1 = "YOOMINA_FENRIR_NEXT_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "마왕이란 존재에 대해 알 수 있는 기회잖아."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "魔王がどんなものかを知るいいチャンスだよ。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Because this is a good opportunity to find out more about the Demon Lord."
L6_1.m_Talk_ENG = L7_1
L7_1 = "可是，這是個了解魔王這種存在的機會不是嘛。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เพราะนี่เป็นโอกาสที่จะได้ข้อมูลเรื่องเจ้าแห่งดีม่อนมากขึ้นไงล่ะ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Vì đây là cơ hội tốt để tìm hiểu thêm về Chúa Quỷ."
L6_1.m_Talk_VTN = L7_1
L7_1 = "可是，这是个了解魔王这种存在的机会不是吗。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Weil dies eine gute Gelegenheit ist, mehr über den Dämonenfürsten herauszufinden."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Eh bien, parce que c'est le moment où jamais d'en apprendre plus sur les Seigneurs démons."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP10_ACT1_INTERLUDE2@207#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 422
L7_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "YOOMINA_FENRIR_NEXT_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L8_1 = "적에 대해 파악하는 건 용병으로서 당연히 해야 할 일 아냐?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "敵について把握することは、傭兵として当然じゃない？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Isn't it our job as mercenaries to analyze the enemy?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "了解敵人，不是身為傭兵應該做的事嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ทหารรับจ้างอย่างมีหน้าที่ต้องวิเคราะห์ศัตรูไม่ใช่เหรอ?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Không phải lính đánh thuê chúng ta phải phân tích kẻ thù sao?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "了解敌人，不是身为佣兵应该做的事吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ist es nicht unsere Aufgabe als Söldner, den Feind zu analysieren?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "On est des mercenaires, non ? La collecte d'infos aussi, ça fait partie du boulot."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
