L10_1 = "EP10_ACT1_INTERLUDE2@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 422
L9_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "SEO_YOON_ALT_CA_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "리플레이서 비숍 때처럼, 레이 선배란 사람에게 아직 미련이 남아 있는 게 아니라?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "リプレイサー・ビショップの時のように、レイ先輩という人にまだ未練があるんじゃなくて？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Aren't you still hung up on Ray, just like that time with Replacer Bishop?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "你不是像克隆·大主教那時那樣，還對雷伊前輩這個人懷有留戀吧？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "นี่เธอไม่ได้ยังยึดติดเรื่องเรย์ เหมือนเรื่องรีเพลสเซอร์ บิช็อปตอนนั้นใช่มั้ย?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Không phải cô vẫn tin Ray đấy chứ, giống như hồi với Quân Tượng Nhân Bản?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "你不会是像克隆·大主教那时一样，还对雷伊这个人怀有留恋吧？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Hängst du etwa immer noch an Ray, genau wie du damals an dem Replacer-Bishop gehangen hast?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "C'est surtout que tu es encore attachée à Ray, non ? Comme pour le Fou des substituts..."
L9_1.m_Talk_FRA = L10_1
