L12_1 = "SEO_YOON_ALT_CA_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "네 심정은 알겠어."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "あなたの気持ちはわかる。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I understand how you feel."
L11_1.m_Talk_ENG = L12_1
L12_1 = "我理解你的心情。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฉันเข้าใจนะว่าเธอรู้สึกยังไง"
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi hiểu cô cảm thấy thế nào."
L11_1.m_Talk_VTN = L12_1
L12_1 = "我理解你的心情。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ich verstehe, wie du dich fühlst."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je sais ce que tu ressens."
L11_1.m_Talk_FRA = L12_1
