L13_1 = "EP10_ACT1_INTERLUDE2@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 422
L12_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "SEO_YOON_ALT_CA_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "그렇지만 이번에는 리플레이서 때와 경우가 달라. 그건 잊지 마."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "でも今回はリプレイサーのときとは訳が違うの。それを忘れないで。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "But this is different from back then. Don't forget that."
L12_1.m_Talk_ENG = L13_1
L13_1 = "不過這次和克隆集團那時的情況不一樣。這一點你別忘了。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "แต่นี่มันไม่เหมือนตอนนั้นนะ อย่าลืมซะล่ะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nhưng bây giờ rất khác. Đừng quên điều đó."
L12_1.m_Talk_VTN = L13_1
L13_1 = "不过这次和克隆集团那时的情况不一样。这一点你别忘了。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Aber das hier ist anders als damals. Vergiss das nicht."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Mais cette fois-ci, c'est différent. Ne l'oublie pas."
L12_1.m_Talk_FRA = L13_1
