L15_1 = "YOOMINA_FENRIR_NEXT_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "……그런 건 나도 알고 있어."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "……そんなのわかってるよ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "...I know that already."
L14_1.m_Talk_ENG = L15_1
L15_1 = "……我也知道這些。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "...ก็รู้อยู่แล้วแหละน่า"
L14_1.m_Talk_THA = L15_1
L15_1 = "...Tôi biết."
L14_1.m_Talk_VTN = L15_1
L15_1 = "……我也知道这些。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "... Dessen bin ich mir durchaus bewusst."
L14_1.m_Talk_DEU = L15_1
L15_1 = "... Je sais bien."
