L18_1 = "EP10_ACT1_INTERLUDE2@217#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 217
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 422
L17_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_DESPAIR"
L18_1 = "YOOMINA_FENRIR_NEXT_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "L"
L18_1 = "선배도 내가 괜한 선택을 했다고 생각해?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "先輩も私が余計な選択をしたと思う？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Do you also think I made a bad decision, Shiyoon?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "前輩也覺得我做了不該做的選擇嗎？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "นายก็คิดว่าฉันตัดสินใจผิดรึเปล่า ชิยุน?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Anh cũng nghĩ tôi đã đưa ra một quyết định tồi tệ sao, Shiyoon?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "前辈也觉得我做了不该做的选择吗？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Findest du auch, dass ich eine schlechte Entscheidung getroffen habe, Shiyoon?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Dis, Charles. Tu crois que j'ai pris la mauvaise décision ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP10_ACT1_INTERLUDE2@218#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 218
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 422
L18_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "R"
L19_1 = "하하, 모든 사람이 만족하는 선택은 도시전설 같은 거예요, 미나 양."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ハハ、全員が満足できる選択なんて、夢物語のようなものなんですよ、ミナさん。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Ha ha, you know you can't please everyone, Mina."
L18_1.m_Talk_ENG = L19_1
L19_1 = "哈哈，怎麼可能會有讓所有人都滿意的選擇呢，米娜。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ฮ่าฮ่า เธอก็รู้นี่ว่าคนเราทำให้ทุกคนพอใจไม่ได้หรอก"
L18_1.m_Talk_THA = L19_1
L19_1 = "Ha ha, cô biết mình chẳng thể khiến tất cả mọi người hài lòng mà, Mina."
L18_1.m_Talk_VTN = L19_1
L19_1 = "哈哈，怎么可能会有让所有人都满意的选择呢，米娜。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Haha, man kann es nicht jedem recht machen, Mina."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Ha ha. On ne peut pas plaire à tout le monde, Mina. C'est la vie."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP10_ACT1_INTERLUDE2@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 422
L19_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_IDLE"
L20_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L20_1 = "저는 서윤 양과 다르게 조금 궁금하긴 하던데요?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "僕はシズカさんとは違って、少し知りたくはなりましたよ？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "I do have to admit that I'm curious, unlike Seo Yoon."
L19_1.m_Talk_ENG = L20_1
L20_1 = "我和徐芸不同，我有一點好奇呢？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ยอมรับนะว่าผมก็สงสัย แต่คนละเรื่องกับซอ ยุน"
L19_1.m_Talk_THA = L20_1
L20_1 = "Tôi phải thừa nhận mình rất tò mò, không giống như Seo Yoon."
L19_1.m_Talk_VTN = L20_1
L20_1 = "和徐芸小姐不同，我有一点好奇呢？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Ich muss zugeben, dass ich im Gegensatz zu Seo Yoon ein wenig neugierig bin."
L19_1.m_Talk_DEU = L20_1
L20_1 = "De mon côté, je dois dire que je suis plutôt curieux."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP10_ACT1_INTERLUDE2@220#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 220
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 422
L20_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "R"
L21_1 = "왜 저 사람들이 세상을 멸망시키려고 그렇게 애를 썼는지 말입니다."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "なんであの人たちが、あれほど世界を滅亡させようと必死だったのか。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I want to know why they tried so hard to put an end to the world."
L20_1.m_Talk_ENG = L21_1
L21_1 = "為什麼那些人會煞費苦心地想要毀滅我們的世界。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ผมอยากรู้ว่าทำไมพวกมันถึงอยากให้จักรวาลนี้ถึงจุดจบขนาดนั้น"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tôi muốn biết tại sao họ lại cố gắng đến thế để chấm dứt vũ trụ này."
L20_1.m_Talk_VTN = L21_1
L21_1 = "为什么那些人会煞费苦心地想要毁灭我们的世界。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ich möchte wissen, warum sie so sehr versucht haben, die Welt zu zerstören."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Curieux de voir ce qui a poussé ces gens-là à être aussi déterminés que ça à détruire notre monde."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP10_ACT1_INTERLUDE2@221#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 221
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 422
L21_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE2"
L21_1.m_bWaitClick = true
