L23_1 = "YOOMINA_FENRIR_NEXT_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "L"
L23_1 = "혹시나, 만에 하나지만 여기서 답을 찾는다면……."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "もし、万が一だけど、ここでその答えを見つけることができれば……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "If, and I mean IF we find the answer here..."
L22_1.m_Talk_ENG = L23_1
L23_1 = "萬一，萬一能在這裡找到答案……"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ถ้านะ ถ้าเราหาคำตอบเจอที่นี่..."
L22_1.m_Talk_THA = L23_1
L23_1 = "Nếu, ý tôi là NẾU chúng ta tìm thấy câu trả lời ở đây..."
L22_1.m_Talk_VTN = L23_1
L23_1 = "万一，万一能在这里找到答案……"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Sollten wir hier wirklich die Antwort finden ..."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Si, et je dis bien SI nous trouvons des réponses ici..."
L22_1.m_Talk_FRA = L23_1
