L26_1 = "YOOMINA_FENRIR_NEXT_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "레이 선배를 멈출 기회는… 아직 남아 있다고 생각해."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "レイ先輩を止めるチャンスは……まだ残っていると思うんだ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I think there is still a chance... that we might be able to stop Ray."
L25_1.m_Talk_ENG = L26_1
L26_1 = "我認為……還有機會阻止雷伊前輩。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ฉันว่าเราก็ยังมีโอกาส... ที่จะหยุดเรย์ได้"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi nghĩ vẫn còn cơ hội... để chúng ta chặn đứng Ray."
L25_1.m_Talk_VTN = L26_1
L26_1 = "我认为……还有机会阻止雷伊前辈。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Denke ich, dass immer noch die Chance besteht ... dass wir Ray aufhalten können."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Alors peut-être que nous aurons encore une chance d'arrêter Ray."
L25_1.m_Talk_FRA = L26_1
